window.FAQ=(window.FAQ||[]).concat([
 {id:'hnx-001',thema:'hypotheek-normen',vraag:'Telt structureel overwerk mee in het toetsinkomen?',antwoord:`Overwerk telt alleen mee als het structureel en voldoende zeker is. Geldverstrekkers willen meestal zien dat het over een langere periode is ontvangen. De werkgeversverklaring moet het structurele karakter bevestigen, of het blijkt uit IBL. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['overwerk','variabel inkomen','toetsinkomen'],bron:''},
 {id:'hnx-002',thema:'hypotheek-normen',vraag:'Hoe ga je om met een onregelmatigheidstoeslag of ploegentoeslag?',antwoord:`Een toeslag die vast onderdeel is van het arbeidspatroon kan meetellen. Voorwaarde is dat de klant naar verwachting in hetzelfde rooster blijft werken. Laat de werkgever dit vermelden in de werkgeversverklaring. Bij twijfel geeft IBL vaak een objectiever beeld.
B:`,tags:['ort','ploegentoeslag','toetsinkomen'],bron:''},
 {id:'hnx-003',thema:'hypotheek-normen',vraag:'Telt provisie of een bonus mee voor het toetsinkomen?',antwoord:`Provisie en bonus tellen alleen mee als ze voldoende bestendig zijn. Geldverstrekkers kijken meestal naar de historie over meerdere jaren. Soms nemen ze alleen een gemiddelde of het laagste jaar mee. Een eenmalige bonus telt in de regel niet mee.
B:`,tags:['provisie','bonus','variabel inkomen'],bron:''},
 {id:'hnx-004',thema:'hypotheek-normen',vraag:'Telt een vaste dertiende maand mee?',antwoord:`Een vaste, onvoorwaardelijke dertiende maand telt in de regel mee. Hij moet dan als vast inkomensbestanddeel in de werkgeversverklaring of de cao staan. Een winstafhankelijke uitkering is variabel en telt alleen mee als die bestendig is. Leg de bron van de uitkering vast in het dossier.
B:`,tags:['dertiende maand','eindejaarsuitkering','toetsinkomen'],bron:''},
 {id:'hnx-005',thema:'hypotheek-normen',vraag:'Hoe behandel je een individueel keuzebudget in het toetsinkomen?',antwoord:`Een individueel keuzebudget vervangt vaak vakantiegeld en eindejaarsuitkering. Of het meetelt, hangt af van de vaste aard van het budget en de vraag of het wordt uitbetaald. Laat de werkgever de hoogte en de aard van het budget specificeren. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['ikb','keuzebudget','toetsinkomen'],bron:''},
 {id:'hnx-006',thema:'hypotheek-normen',vraag:'Telt de bijtelling van een leaseauto mee als inkomen?',antwoord:`Nee, de bijtelling is een fiscale correctie en geen inkomen dat de klant ontvangt. Neem de bijtelling dus niet op in het toetsinkomen. Let op dat sommige overzichten fiscale loonbegrippen gebruiken. Controleer of de bijtelling er correct uit is gehaald.
B:`,tags:['leaseauto','bijtelling','toetsinkomen'],bron:''},
 {id:'hnx-007',thema:'hypotheek-normen',vraag:'Hoe ga je om met een klant die nog in de proeftijd zit?',antwoord:`Geldverstrekkers accepteren inkomen tijdens de proeftijd vaak niet of alleen onder voorwaarden. Soms volstaat een verklaring van de werkgever over het verloop van de proeftijd. Een andere optie is passeren na afloop van de proeftijd. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['proeftijd','loondienst','acceptatie'],bron:''},
 {id:'hnx-008',thema:'hypotheek-normen',vraag:'Telt het inkomen uit een nieuwe baan die nog moet ingaan mee?',antwoord:`Toekomstig inkomen uit een nieuwe baan kan meetellen als er een getekende arbeidsovereenkomst ligt. Geldverstrekkers stellen vaak eisen aan de termijn tot de ingangsdatum. Bij een tijdelijk contract of een proeftijd gelden extra eisen. Leg de ingangsdatum en de contractvoorwaarden vast in het dossier.
B:`,tags:['nieuwe baan','arbeidsovereenkomst','toetsinkomen'],bron:''},
 {id:'hnx-009',thema:'hypotheek-normen',vraag:'Mag een aangekondigde loonsverhoging meetellen?',antwoord:`Alleen een verhoging die vaststaat en onvoorwaardelijk is, komt in aanmerking. Denk aan een cao-verhoging met een vaste ingangsdatum of een schriftelijk toegezegde periodiek. Een verwachte of voorwaardelijke verhoging telt niet mee. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['loonsverhoging','cao','toetsinkomen'],bron:''},
 {id:'hnx-010',thema:'hypotheek-normen',vraag:'Hoe toets je een klant met twee parttime dienstverbanden?',antwoord:`Je telt de inkomens uit beide dienstverbanden op, mits elk inkomen voldoende zeker is. Voor elke werkgever is een eigen onderbouwing nodig. Is een van de contracten tijdelijk, dan gelden voor dat deel de eisen voor tijdelijke contracten. Leg per inkomensbron de onderbouwing vast.
B:`,tags:['parttime','meerdere werkgevers','toetsinkomen'],bron:''},
 {id:'hnx-011',thema:'hypotheek-normen',vraag:'Hoe beoordeel je het inkomen van een uitzendkracht?',antwoord:`Uitzendwerk geldt meestal als flexibel inkomen. Afhankelijk van de fase en het contract kan een verklaring van de uitzendonderneming bruikbaar zijn. Vaak is IBL of een perspectiefverklaring de praktische route. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['uitzendkracht','flexibel inkomen','ibl'],bron:''},
 {id:'hnx-012',thema:'hypotheek-normen',vraag:'Hoe toets je een oproepkracht of een nulurencontract?',antwoord:`Bij een oproepcontract is het aantal uren niet gegarandeerd. Een werkgeversverklaring geeft daarom weinig zekerheid over het inkomen. De toetsing loopt meestal via IBL of een perspectiefverklaring. Leg vast waarom het gebruikte inkomen als bestendig wordt gezien.
B:`,tags:['nulurencontract','oproepkracht','flexibel inkomen'],bron:''},
 {id:'hnx-013',thema:'hypotheek-normen',vraag:'Telt inkomen via een payrollconstructie als loondienst?',antwoord:`Bij payrolling is de werknemer formeel in dienst van de payrollonderneming. Voor de toets gaat het om de aard van het contract: onbepaalde of bepaalde tijd. Een payrollcontract voor onbepaalde tijd wordt vaak als gewone loondienst behandeld. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['payroll','loondienst','contractvorm'],bron:''},
 {id:'hnx-014',thema:'hypotheek-normen',vraag:'Wat doe je als werkgeversverklaring en salarisstrook niet overeenkomen?',antwoord:`Verklaar het verschil voordat je de aanvraag indient. Denk aan een recente loonsverhoging, een gewijzigde urenomvang of een fout van de werkgever. Vraag zo nodig een gecorrigeerde verklaring op. Leg de verklaring van het verschil vast in het dossier.
B:`,tags:['werkgeversverklaring','salarisstrook','controle'],bron:''},
 {id:'hnx-015',thema:'hypotheek-normen',vraag:'Hoe oud mag een werkgeversverklaring zijn?',antwoord:`Geldverstrekkers stellen een maximale ouderdom aan inkomensstukken. Die termijn verschilt per geldverstrekker en per document. Een verlopen stuk leidt vaak tot vertraging in de acceptatie. Controleer de termijnen al bij het opvragen van de stukken.
B:`,tags:['werkgeversverklaring','ouderdom','documenten'],bron:''},
 {id:'hnx-016',thema:'hypotheek-normen',vraag:'Wie mag een werkgeversverklaring ondertekenen?',antwoord:`Een daartoe bevoegde persoon bij de werkgever ondertekent de verklaring. De klant mag zijn eigen verklaring niet ondertekenen. Bij een familiebedrijf of eigen bv gelden vaak extra eisen, omdat de klant invloed op het salaris kan hebben. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['werkgeversverklaring','ondertekening','fraude'],bron:''},
 {id:'hnx-017',thema:'hypotheek-normen',vraag:'Hoe beoordeel je een klant die in loondienst is bij een familielid?',antwoord:`Bij een dienstverband bij familie kan de onafhankelijkheid van de werkgever ter discussie staan. Geldverstrekkers vragen dan vaak extra stukken, zoals jaarcijfers van het bedrijf. Soms beoordelen zij de klant als ondernemer. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['familiebedrijf','loondienst','acceptatie'],bron:''},
 {id:'hnx-018',thema:'hypotheek-normen',vraag:'Telt inkomen van een werkgever in het buitenland mee?',antwoord:`Buitenlands inkomen kan meetellen, maar veel geldverstrekkers stellen extra eisen. Denk aan vertaalde stukken, het land van belastingheffing en de rechtspositie van de werknemer. Sommige geldverstrekkers accepteren dit inkomen niet. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['buitenland','grensarbeider','toetsinkomen'],bron:''},
 {id:'hnx-019',thema:'hypotheek-normen',vraag:'Hoe ga je om met inkomen in een vreemde valuta?',antwoord:`De klant loopt dan een wisselkoersrisico, terwijl de lasten in euro zijn. Geldverstrekkers rekenen soms met een afslag of accepteren dit inkomen niet. Bespreek het valutarisico met de klant. Leg de afweging en de gebruikte koers vast in het dossier.
B:`,tags:['valuta','wisselkoers','buitenland'],bron:''},
 {id:'hnx-020',thema:'hypotheek-normen',vraag:'Telt het inkomen mee tijdens ouderschapsverlof?',antwoord:`Tijdens onbetaald of deels betaald verlof is het werkelijke inkomen tijdelijk lager. Loopt het dienstverband door, dan is het structurele inkomen meestal het uitgangspunt. Laat de werkgever het reguliere inkomen en de verlofperiode vermelden. Bespreek of de klant de lasten tijdens het verlof kan dragen.
B:`,tags:['ouderschapsverlof','verlof','toetsinkomen'],bron:''},
 {id:'hnx-021',thema:'hypotheek-normen',vraag:'Waar let je op bij zwangerschapsverlof in combinatie met een tijdelijk contract?',antwoord:`Tijdens het verlof loopt het dienstverband door, dus het reguliere inkomen is het uitgangspunt. Het risico zit in een contract dat tijdens of kort na het verlof afloopt. Dan gelden de eisen voor tijdelijke contracten, zoals een intentieverklaring. Leg de contractsituatie vast in het dossier.
B:`,tags:['zwangerschapsverlof','tijdelijk contract','intentieverklaring'],bron:''},
 {id:'hnx-022',thema:'hypotheek-normen',vraag:'Hoe toets je een klant die langdurig ziek is?',antwoord:`Bij langdurige ziekte is het toekomstige inkomen onzeker. Geldverstrekkers kijken naar de situatie na afloop van de loondoorbetaling. Een mogelijke WIA-uitkering is dan relevant. Bespreek het risico met de klant en leg de afweging vast in het dossier.
B:`,tags:['ziekte','loondoorbetaling','wia'],bron:''},
 {id:'hnx-023',thema:'hypotheek-normen',vraag:'Telt een tijdelijke uitbreiding van de arbeidsuren mee?',antwoord:`Een tijdelijke urenuitbreiding telt in de regel niet mee. Alleen een structureel vastgelegde uitbreiding kan in het toetsinkomen worden opgenomen. Laat de werkgever dit expliciet bevestigen. Leg de onderbouwing vast in het dossier.
B:`,tags:['urenuitbreiding','deeltijd','toetsinkomen'],bron:''},
 {id:'hnx-024',thema:'hypotheek-normen',vraag:'Wat doe je als de klant na de aankoop minder gaat werken?',antwoord:`De rekennorm kijkt naar het huidige structurele inkomen. De zorgplicht vraagt dat je ook een bekende toekomstige daling meeweegt. Toets daarom ook of de lasten na de urenvermindering betaalbaar blijven. Leg de geplande wijziging en de afweging vast in het dossier.`,tags:['urenvermindering','zorgplicht','betaalbaarheid'],bron:'Wft'},
 {id:'hnx-025',thema:'hypotheek-normen',vraag:'Telt een vaste reiskostenvergoeding mee als inkomen?',antwoord:`Een onkostenvergoeding dekt kosten en is geen loon voor de toets. Reiskostenvergoedingen tellen daarom in de regel niet mee. Hetzelfde geldt voor andere kostenvergoedingen, zoals een thuiswerkvergoeding. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['reiskosten','vergoeding','toetsinkomen'],bron:''},
 {id:'hnx-026',thema:'hypotheek-normen',vraag:'Telt het inkomen van een gedetacheerde werknemer als loondienst?',antwoord:`Ja, bij detachering is de werknemer in dienst van de detacheerder. Beslissend is het contract met de detacheerder, niet de duur van de lopende opdracht. Een vast contract met de detacheerder geldt als vast dienstverband. Vraag de werkgeversverklaring op bij de detacheerder.
B:`,tags:['detachering','loondienst','contractvorm'],bron:''},
 {id:'hnx-027',thema:'hypotheek-normen',vraag:'Wat doe je als de werkgever tijdens het aanvraagtraject failliet gaat?',antwoord:`Het inkomen is dan niet meer zeker. Meld de wijziging direct aan de geldverstrekker. De aanvraag moet opnieuw worden beoordeeld op basis van de nieuwe situatie. Leg de communicatie en de gevolgen vast in het dossier.
B:`,tags:['faillissement','werkgever','meldplicht'],bron:''},
 {id:'hnx-028',thema:'hypotheek-normen',vraag:'Moet je een gewijzigde inkomenssituatie na de offerte melden?',antwoord:`Ja. De geldverstrekker heeft de offerte uitgebracht op basis van de verstrekte gegevens. Een wezenlijke wijziging kan de beoordeling veranderen. Meld de wijziging en leg vast wanneer en hoe dat is gebeurd.
B:`,tags:['offerte','inkomenswijziging','meldplicht'],bron:''},
 {id:'hnx-029',thema:'hypotheek-normen',vraag:'Hoe kijk je naar het inkomen tijdens een sabbatical?',antwoord:`Tijdens een sabbatical is er vaak tijdelijk geen of minder inkomen. Loopt het dienstverband door en ligt de terugkeer vast, dan kijken geldverstrekkers vaak naar het reguliere inkomen. De klant moet de lasten tijdens de sabbatical wel kunnen dragen. Leg de afweging vast in het dossier.
B:`,tags:['sabbatical','verlof','betaalbaarheid'],bron:''},
 {id:'hnx-030',thema:'hypotheek-normen',vraag:'Hoe toets je een werknemer met een jaarurencontract?',antwoord:`Bij een jaarurencontract wisselt het inkomen per maand, maar ligt het jaarsalaris vast. Het vaste jaarsalaris is dan het uitgangspunt. Extra uren boven het contract tellen alleen mee als ze bestendig zijn. Laat de werkgever de afspraken specificeren.
B:`,tags:['jaarurencontract','loondienst','toetsinkomen'],bron:''},
 {id:'hnx-031',thema:'hypotheek-normen',vraag:'Telt een vergoeding voor een bestuurs- of toezichtsfunctie mee?',antwoord:`Een vergoeding uit een nevenfunctie kan meetellen als die structureel is. Geldverstrekkers kijken naar de duur van de benoeming en de historie. Een benoeming voor bepaalde tijd geeft minder zekerheid. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['nevenfunctie','toezichthouder','inkomen'],bron:''},
 {id:'hnx-032',thema:'hypotheek-normen',vraag:'Wat is het verschil tussen een werkgeversverklaring en IBL in de praktijk?',antwoord:`Een werkgeversverklaring geeft het actuele inkomen zoals de werkgever dat opgeeft. IBL gebruikt geregistreerde loongegevens uit het UWV-verzekeringsbericht over een langere periode. IBL is daardoor minder gevoelig voor fouten in een verklaring, maar volgt de historie. Kies de methode die de situatie het best weergeeft en leg die keuze vast.`,tags:['ibl','werkgeversverklaring','methode'],bron:'Voorwaarden & Normen NHG'},
 {id:'hnx-033',thema:'hypotheek-normen',vraag:'Hoe ga je om met een loonbeslag?',antwoord:`Een loonbeslag wijst op een schuld die niet is voldaan. Geldverstrekkers zien dit meestal als een ernstig signaal. Breng de onderliggende schuld in kaart en neem de maandlast mee in de beoordeling. Leg de beoordeling vast in het dossier.
B:`,tags:['loonbeslag','schulden','acceptatie'],bron:''},
 {id:'hnx-034',thema:'hypotheek-normen',vraag:'Welke methode gebruik je als IBL lager uitkomt dan de werkgeversverklaring?',antwoord:`Dat kan gebeuren na een recente loonsverhoging of urenuitbreiding. Bij een vast contract kun je vaak kiezen voor de methode die het structurele inkomen het best weergeeft. Kies niet alleen op basis van de hoogste uitkomst. Controleer de voorwaarden van de geldverstrekker en leg de keuze vast.
B:`,tags:['ibl','werkgeversverklaring','inkomensbepaling'],bron:''},
 {id:'hnx-035',thema:'hypotheek-normen',vraag:'Welke gegevens controleer je in een UWV-verzekeringsbericht?',antwoord:`Controleer de dienstverbanden, de ingangsdata, het loon per periode en eventuele uitkeringen. Kijk of alle werkgevers zichtbaar zijn en of er gaten in de historie zitten. Vergelijk de gegevens met de salarisstroken. Leg afwijkingen en de verklaring daarvan vast.
B:`,tags:['uwv','verzekeringsbericht','controle'],bron:''},
 {id:'hnx-036',thema:'hypotheek-normen',vraag:'Mag de klant het UWV-verzekeringsbericht zelf aanleveren?',antwoord:`Ja, de klant haalt het bericht doorgaans zelf op via de persoonlijke omgeving van UWV. Geldverstrekkers stellen eisen aan het bestandsformaat en de ouderdom. Een bewerkt of omgezet bestand wordt vaak niet geaccepteerd. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['uwv','ibl','documenten'],bron:''},
 {id:'hnx-037',thema:'hypotheek-normen',vraag:'Telt inkomen uit een stage of leerwerktraject mee?',antwoord:`Een stagevergoeding is meestal tijdelijk en telt dan niet mee. Bij een leerwerkovereenkomst hangt het af van het contract en het perspectief na afloop. Een intentieverklaring of perspectiefverklaring kan uitkomst bieden. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['stage','leerwerktraject','toetsinkomen'],bron:''},
 {id:'hnx-038',thema:'hypotheek-normen',vraag:'Tellen fooien mee als inkomen?',antwoord:`Fooien zijn variabel en vaak slecht aantoonbaar. Alleen fooien die via de loonadministratie lopen, zijn zichtbaar in het loon. Contant ontvangen fooien tellen in de regel niet mee. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['fooien','variabel inkomen','horeca'],bron:''},
 {id:'hnx-039',thema:'hypotheek-normen',vraag:'Hoe ga je om met een lening van de werkgever?',antwoord:`Een lening van de werkgever is een verplichting van de klant. Wordt de aflossing ingehouden op het salaris, dan is het beschikbare inkomen lager. Neem de maandlast mee in de beoordeling. Controleer hoe de geldverstrekker deze verplichting meetelt.
B:`,tags:['werkgeverslening','verplichtingen','inhouding'],bron:''},
 {id:'hnx-040',thema:'hypotheek-normen',vraag:'Hoe weeg je een aangekondigde reorganisatie bij de werkgever?',antwoord:`Een aangekondigde reorganisatie maakt het inkomen minder zeker. Formeel kan een vast contract nog steeds aan de eisen voldoen. De zorgplicht vraagt wel dat je het risico met de klant bespreekt. Leg het gesprek en de afweging vast in het dossier.`,tags:['reorganisatie','zorgplicht','inkomensrisico'],bron:'Wft'},
 {id:'hnx-041',thema:'hypotheek-normen',vraag:'Telt een jubileumuitkering of andere eenmalige gratificatie mee?',antwoord:`Een eenmalige uitkering is niet structureel en telt niet mee in het toetsinkomen. Zulke bedragen kunnen wel zichtbaar zijn in loongegevens of op een salarisstrook. Beoordeel daarom of het gebruikte inkomen alleen structurele delen bevat. Leg vast welke posten je hebt uitgesloten.
B:`,tags:['gratificatie','eenmalig','toetsinkomen'],bron:''},
 {id:'hnx-042',thema:'hypotheek-normen',vraag:'Hoe kijk je naar een reeks tijdelijke contracten bij dezelfde werkgever?',antwoord:`Een reeks tijdelijke contracten kan wijzen op een duurzame arbeidsrelatie. Formeel blijft het wel een tijdelijk dienstverband. Een intentieverklaring of IBL kan dan de basis vormen. Let ook op de arbeidsrechtelijke ketenregeling en controleer de voorwaarden van de geldverstrekker.
B:`,tags:['tijdelijk contract','ketenregeling','intentieverklaring'],bron:''},
 {id:'hnx-043',thema:'hypotheek-normen',vraag:'Welk inkomen gebruik je na een loonsverlaging door een functiewijziging?',antwoord:`Het toetsinkomen is het nieuwe, lagere inkomen. Het eerdere hogere inkomen is niet meer structureel. Bij IBL kan een historie met hoger loon het beeld vertekenen. Leg de wijziging en het gebruikte inkomen vast in het dossier.
B:`,tags:['loonsverlaging','functiewijziging','toetsinkomen'],bron:''},
 {id:'hnx-044',thema:'hypotheek-normen',vraag:'Telt het inkomen van een inwonend kind mee?',antwoord:`Inkomen van inwonende kinderen telt in de regel niet mee. Alleen het inkomen van de aanvragers die de lening aangaan, telt. Wordt een kind medeaanvrager, dan wordt het ook hoofdelijk aansprakelijk. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['inwonend kind','toetsinkomen','aanvragers'],bron:''},
 {id:'hnx-045',thema:'hypotheek-normen',vraag:'Kan een ouder als medeaanvrager het toetsinkomen verhogen?',antwoord:`Sommige geldverstrekkers staan toe dat een ouder als medeschuldenaar meetekent. Het inkomen van de ouder telt dan mee, maar de ouder wordt ook hoofdelijk aansprakelijk. Een ouder die er niet woont, heeft fiscaal geen eigen woning in die woning. Bespreek de risicos met beide partijen en controleer de voorwaarden.
B:`,tags:['medeaanvrager','ouder','hoofdelijkheid'],bron:''},
 {id:'hnx-046',thema:'hypotheek-normen',vraag:'Wat als een tijdelijk contract afloopt vóór de passeerdatum?',antwoord:`Loopt het contract zonder verlenging af voor het passeren, dan ontbreekt zeker inkomen. Een verlenging of nieuw contract moet dan vastliggen. Anders kan IBL of een perspectiefverklaring een route zijn. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['tijdelijk contract','passeerdatum','inkomen'],bron:''},
 {id:'hnx-047',thema:'hypotheek-normen',vraag:'Hoe reken je een salarisstrook om naar een bruto jaarinkomen?',antwoord:`Vermenigvuldig het vaste bruto salaris met het aantal betalingen per jaar. Bij betaling per vier weken zijn dat dertien perioden, niet twaalf. Tel daarna vakantiegeld en vaste uitkeringen op. Leg de berekening vast in het dossier.
B:`,tags:['jaarinkomen','vierwekenloon','berekening'],bron:''},
 {id:'hnx-048',thema:'hypotheek-normen',vraag:'Hoe ga je om met een salarisstrook met een eenmalige correctie?',antwoord:`Een nabetaling of correctie vertekent het maandloon. Gebruik het reguliere bruto loon zonder eenmalige posten. Vraag zo nodig een strook van een andere maand op. Leg vast welke strook je hebt gebruikt en waarom.
B:`,tags:['salarisstrook','correctie','nabetaling'],bron:''},
 {id:'hnx-049',thema:'hypotheek-normen',vraag:'Hoe toets je een klant in dienst van een jonge onderneming?',antwoord:`Een jonge onderneming geeft minder zekerheid over de continuïteit van de werkgever. Sommige geldverstrekkers vragen dan extra informatie over de werkgever. Een vast contract blijft het formele uitgangspunt. Bespreek het risico en controleer de voorwaarden van de geldverstrekker.
B:`,tags:['werkgever','continuiteit','acceptatie'],bron:''},
 {id:'hnx-050',thema:'hypotheek-normen',vraag:'Wat zijn veelgemaakte fouten bij het bepalen van loondienstinkomen?',antwoord:`Veel fouten zijn rekenkundig of administratief:
- vakantiegeld vergeten of dubbel tellen
- een vierwekensalaris behandelen als maandsalaris
- eenmalige uitkeringen meetellen
- de bijtelling van een leaseauto niet uitsluiten
- variabel inkomen gebruiken zonder onderbouwing
Controleer de berekening altijd tegen de stukken.
B:`,tags:['fouten','loondienst','controle'],bron:''},
 {id:'hnx-051',thema:'hypotheek-normen',vraag:'Hoe ga je om met een ondernemer die één slecht jaar had door eenmalige omstandigheden?',antwoord:`Veel rekenmethoden begrenzen het inkomen op het laatste jaar als dat lager is dan het gemiddelde. Een verklaarbaar eenmalig slecht jaar kan soms worden gecorrigeerd met een onderbouwing van een rekenexpert. Dat is een beoordeling van de geldverstrekker. Leg de oorzaak en de onderbouwing vast in het dossier.
B:`,tags:['ondernemer','slecht jaar','inkomensverklaring'],bron:''},
 {id:'hnx-052',thema:'hypotheek-normen',vraag:'Gebruik je de winst vóór of na de ondernemersaftrek?',antwoord:`Gebruikelijk is uit te gaan van de winst uit onderneming vóór de ondernemersaftrek. De ondernemersaftrek is een fiscale faciliteit en geen bedrijfskost. Rekenexperts en geldverstrekkers hanteren hiervoor eigen methoden. Controleer de rekenmethode van de geldverstrekker.
B:`,tags:['ondernemersaftrek','winst','ondernemer'],bron:''},
 {id:'hnx-053',thema:'hypotheek-normen',vraag:'Hoe beoordeel je een ondernemer die net van eenmanszaak naar bv is overgestapt?',antwoord:`De bedrijfshistorie loopt door, maar het inkomen bestaat voortaan uit salaris en winst in de bv. Geldverstrekkers kijken daarom naar de cijfers van de eenmanszaak en de bv samen. Een rekenexpert kan het inkomen over beide rechtsvormen bepalen. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['bv','eenmanszaak','rechtsvormwijziging'],bron:''},
 {id:'hnx-054',thema:'hypotheek-normen',vraag:'Hoe toets je een DGA die weinig salaris neemt en winst in de bv laat?',antwoord:`Het salaris alleen geeft dan een onvolledig beeld. Sommige rekenmethoden nemen ook de winst van de bv mee, rekening houdend met de financiële positie van de bv. Of de winst uitkeerbaar is, speelt daarbij een rol. Laat een rekenexpert het inkomen bepalen en controleer de voorwaarden.
B:`,tags:['dga','bv-winst','inkomensverklaring'],bron:''},
 {id:'hnx-055',thema:'hypotheek-normen',vraag:'Hoe toets je een vennoot in een vof of maat in een maatschap?',antwoord:`Een vennoot of maat is ondernemer voor de inkomstenbelasting. Het gaat om het winstaandeel van de aanvrager. Geldverstrekkers kijken naar de cijfers van het samenwerkingsverband en naar de winstverdeling. Vraag de jaarcijfers en de IB-aangiften van de aanvrager op.
B:`,tags:['vof','maatschap','winstaandeel'],bron:''},
 {id:'hnx-056',thema:'hypotheek-normen',vraag:'Hoe toets je een ondernemer die daarnaast in loondienst werkt?',antwoord:`Je beoordeelt beide inkomensbronnen apart. Het loondienstinkomen toets je volgens de eisen voor loondienst. Het ondernemersinkomen toets je met de historie van de onderneming. Tel de uitkomsten op en leg per bron de onderbouwing vast.
B:`,tags:['hybride ondernemer','loondienst','toetsinkomen'],bron:''},
 {id:'hnx-057',thema:'hypotheek-normen',vraag:'Hoe beoordeel je een ondernemer met sterk wisselende winsten?',antwoord:`Bij grote schommelingen geeft een gemiddelde een vertekend beeld. Rekenmethoden begrenzen het inkomen daarom vaak op een lager jaar. Bespreek met de klant of de lasten ook in een slecht jaar te dragen zijn. Leg de afweging vast in het dossier.
B:`,tags:['ondernemer','wisselende winst','betaalbaarheid'],bron:''},
 {id:'hnx-058',thema:'hypotheek-normen',vraag:'Telt een prognose voor het lopende jaar mee bij een ondernemer?',antwoord:`Een prognose geeft geen zekerheid. Geldverstrekkers gebruiken prognoses hooguit aanvullend, bijvoorbeeld bij een korte historie. Het toetsinkomen is in de regel gebaseerd op gerealiseerde cijfers. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['prognose','ondernemer','toetsinkomen'],bron:''},
 {id:'hnx-059',thema:'hypotheek-normen',vraag:'Mag je een inkomensverklaring van een rekenexpert overnemen zonder eigen controle?',antwoord:`Nee, de verklaring is een belangrijke onderbouwing, maar vervangt je eigen beoordeling niet. Controleer of de uitgangspunten passen bij wat je van de klant weet. Let op ontwikkelingen na de laatste cijfers. Leg je eigen beoordeling vast in het dossier.`,tags:['inkomensverklaring','rekenexpert','zorgplicht'],bron:'Wft'},
 {id:'hnx-060',thema:'hypotheek-normen',vraag:'Hoe toets je een ondernemer die binnenkort stopt met de onderneming?',antwoord:`Het ondernemersinkomen is dan niet meer bestendig. De beoordeling moet uitgaan van het inkomen na de stopzetting. Bespreek de gevolgen voor de betaalbaarheid met de klant. Leg de afweging vast in het dossier.
B:`,tags:['stoppen','ondernemer','inkomensdaling'],bron:''},
 {id:'hnx-061',thema:'hypotheek-normen',vraag:'Telt een stakingswinst mee als inkomen?',antwoord:`Nee, een stakingswinst is eenmalig en niet structureel. Corrigeer de jaarcijfers voor eenmalige baten en lasten. Laat de rekenexpert deze correctie expliciet benoemen. Leg vast welke correcties zijn toegepast.
B:`,tags:['stakingswinst','eenmalig','ondernemer'],bron:''},
 {id:'hnx-062',thema:'hypotheek-normen',vraag:'Hoe ga je om met privéopnamen die structureel hoger zijn dan de winst?',antwoord:`Structureel hogere opnamen dan de winst wijzen op interen op vermogen. Dat is een signaal voor de betaalbaarheid. Geldverstrekkers en rekenexperts nemen dit mee in de beoordeling. Bespreek het met de klant en leg het vast.
B:`,tags:['privéopnamen','ondernemer','vermogen'],bron:''},
 {id:'hnx-063',thema:'hypotheek-normen',vraag:'Tellen huurinkomsten uit een tweede woning mee?',antwoord:`Huurinkomsten kunnen bij sommige geldverstrekkers meetellen. Er wordt dan vaak gekeken naar de netto opbrengst na de lasten van het verhuurde pand. De financieringslasten van dat pand moeten ook worden meegewogen. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['huurinkomsten','verhuur','toetsinkomen'],bron:''},
 {id:'hnx-064',thema:'hypotheek-normen',vraag:'Telt rendement op vermogen mee in het toetsinkomen?',antwoord:`Rendement op vermogen is meestal niet zeker genoeg om als toetsinkomen te dienen. Sommige geldverstrekkers houden bij maatwerk wel rekening met vermogen. Vermogen kan ook worden ingezet om de lening te verlagen. Leg de afweging vast in het dossier.
B:`,tags:['vermogen','rendement','toetsinkomen'],bron:''},
 {id:'hnx-065',thema:'hypotheek-normen',vraag:'Hoe toets je een klant met een lijfrente-uitkering?',antwoord:`Een lijfrente-uitkering kan meetellen als die voldoende lang loopt. Een tijdelijke uitkering die binnen afzienbare tijd stopt, geeft minder zekerheid. Kijk naar de einddatum en naar het inkomen daarna. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['lijfrente','uitkering','looptijd'],bron:''},
 {id:'hnx-066',thema:'hypotheek-normen',vraag:'Telt een nabestaandenuitkering mee als toetsinkomen?',antwoord:`Een levenslang nabestaandenpensioen is duurzaam en kan meetellen. Een tijdelijk nabestaandenpensioen of een Anw-uitkering geeft minder zekerheid, omdat die op een bepaald moment eindigt. Let op de einddatum en het inkomen daarna. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['nabestaandenpensioen','anw','toetsinkomen'],bron:''},
 {id:'hnx-067',thema:'hypotheek-normen',vraag:'Telt een WIA-uitkering mee als toetsinkomen?',antwoord:`Een IVA-uitkering is bedoeld voor duurzame volledige arbeidsongeschiktheid en geldt meestal als duurzaam. Bij een WGA-uitkering hangt het af van de fase en de verwachte duur. Geldverstrekkers kijken naar de beschikking van UWV. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['wia','iva','wga'],bron:''},
 {id:'hnx-068',thema:'hypotheek-normen',vraag:'Telt een Wajong-uitkering mee?',antwoord:`Een Wajong-uitkering kan duurzaam zijn en dan meetellen. Beoordeel de beschikking en eventuele herbeoordelingen. Let op de hoogte van de uitkering bij gedeeltelijke arbeid. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['wajong','uitkering','toetsinkomen'],bron:''},
 {id:'hnx-069',thema:'hypotheek-normen',vraag:'Telt ontvangen kinderalimentatie mee als inkomen?',antwoord:`Kinderalimentatie is bestemd voor de kosten van het kind en eindigt meestal als het kind volwassen is. Veel geldverstrekkers tellen het daarom niet mee in het toetsinkomen. Betaalde kinderalimentatie raakt wel de betaalbaarheid, ook als de rekennorm er niet direct mee rekent. Controleer de voorwaarden en leg de afweging vast.
B:`,tags:['kinderalimentatie','inkomen','betaalbaarheid'],bron:''},
 {id:'hnx-070',thema:'hypotheek-normen',vraag:'Tellen toeslagen zoals het kindgebonden budget mee?',antwoord:`Toeslagen tellen in de regel niet mee in het toetsinkomen. Ze zijn inkomensafhankelijk en kunnen veranderen of vervallen. Ook de huurtoeslag vervalt na de aankoop van een woning. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['toeslagen','kindgebonden budget','toetsinkomen'],bron:''},
 {id:'hnx-071',thema:'hypotheek-normen',vraag:'Hoe toets je een klant die met vroegpensioen gaat vóór de AOW-leeftijd?',antwoord:`Het inkomen bestaat dan tot de AOW-leeftijd uit pensioen en eventuele tijdelijke uitkeringen. Kijk zowel naar het inkomen vóór als na de AOW-leeftijd. Let op tijdelijke uitkeringen die stoppen. Leg de beoordeling per periode vast in het dossier.
B:`,tags:['vroegpensioen','aow','inkomensdaling'],bron:''},
 {id:'hnx-072',thema:'hypotheek-normen',vraag:'Welke stukken gebruik je om pensioeninkomen aan te tonen?',antwoord:`Voor een ingegaan pensioen een recente uitkeringsspecificatie of jaaropgave van de pensioenuitvoerder. Voor toekomstig pensioen het pensioenoverzicht en mijnpensioenoverzicht.nl. Let op of bedragen bruto en levenslang zijn. Leg de gebruikte bronnen vast.
B:`,tags:['pensioen','documenten','pensioenoverzicht'],bron:''},
 {id:'hnx-073',thema:'hypotheek-normen',vraag:'Hoe bepaal je het toekomstige pensioeninkomen als het pensioen nog niet is ingegaan?',antwoord:`Gebruik het verwachte bruto pensioeninkomen en de AOW. Let op of een overzicht uitgaat van doorgaande opbouw of alleen van opgebouwde aanspraken. Een voorzichtige keuze sluit beter aan bij de zorgplicht. Leg de keuze en de bron vast in het dossier.
B:`,tags:['pensioen','opbouw','aow'],bron:''},
 {id:'hnx-074',thema:'hypotheek-normen',vraag:'Welk AOW-bedrag gebruik je bij samenwonenden?',antwoord:`De AOW voor samenwonenden is lager dan die voor alleenstaanden. Gebruik het bedrag dat past bij de leefsituatie na de aankoop. Raadpleeg het actuele bedrag bij de SVB. Leg vast welk bedrag je hebt gebruikt.`,tags:['aow','samenwonend','svb'],bron:'SVB'},
 {id:'hnx-075',thema:'hypotheek-normen',vraag:'Hoe ga je om met een AOW-gat door wonen in het buitenland?',antwoord:`De AOW wordt opgebouwd over de jaren dat iemand in Nederland verzekerd is. Wie in het buitenland heeft gewoond of gewerkt, kan een lagere AOW krijgen. Gebruik het verwachte bedrag volgens de SVB. Leg de berekening vast in het dossier.`,tags:['aow','buitenland','opbouw'],bron:'SVB'},
 {id:'hnx-076',thema:'hypotheek-normen',vraag:'Telt een buitenlands pensioen mee?',antwoord:`Een buitenlands pensioen kan meetellen als het voldoende zeker en aantoonbaar is. Let op valuta, belastingheffing en de levenslange aard van de uitkering. Niet elke geldverstrekker accepteert dit inkomen. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['buitenlands pensioen','valuta','toetsinkomen'],bron:''},
 {id:'hnx-077',thema:'hypotheek-normen',vraag:'Hoe toets je een klant met WW die net een nieuwe baan heeft?',antwoord:`Het nieuwe dienstverband is leidend, niet de WW-uitkering. Toets het inkomen volgens de eisen voor dat contract, zoals een tijdelijk contract of proeftijd. De WW-uitkering stopt of wordt verrekend. Leg de overgang en de stukken vast in het dossier.
B:`,tags:['ww','nieuwe baan','toetsinkomen'],bron:''},
 {id:'hnx-078',thema:'hypotheek-normen',vraag:'Telt een bijstandsuitkering mee als toetsinkomen?',antwoord:`Een bijstandsuitkering is een vangnet en hangt af van vermogen en leefsituatie. Geldverstrekkers accepteren dit in de regel niet als toetsinkomen. Het aangaan van een hypotheek kan bovendien gevolgen hebben voor de uitkering. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['bijstand','uitkering','toetsinkomen'],bron:''},
 {id:'hnx-079',thema:'hypotheek-normen',vraag:'Hoe combineer je partners met verschillende inkomenssoorten?',antwoord:`Bepaal per partner het toetsinkomen volgens de regels voor die inkomenssoort. Tel de uitkomsten daarna op. Zo combineer je bijvoorbeeld loondienst met ondernemersinkomen. Leg per partner de onderbouwing vast.`,tags:['partners','inkomenssoorten','toetsinkomen'],bron:'Trhk'},
 {id:'hnx-080',thema:'hypotheek-normen',vraag:'Welke financieringslasttabel gebruik je als één partner AOW-gerechtigd is?',antwoord:`Bij een huishouden met één AOW-gerechtigde partner is de tabelkeuze niet vanzelfsprekend. De Trhk bevat hiervoor regels en geldverstrekkers verwerken die in hun rekenmodel. Controleer welke tabel het model heeft toegepast. Leg dat vast en kijk ook naar het inkomen als de andere partner later de AOW-leeftijd bereikt.`,tags:['aow','tabelkeuze','partners'],bron:'Trhk'},
 {id:'hnx-081',thema:'hypotheek-normen',vraag:'Telt een uitkering uit een arbeidsongeschiktheidsverzekering mee?',antwoord:`Een uitkering uit een particuliere AOV kan meetellen als die voldoende duurzaam is. Kijk naar de einddatum, de herbeoordelingen en eventuele beperkingen in de polis. Een uitkering die eindigt op een vaste leeftijd geeft na die leeftijd geen inkomen meer. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['aov','arbeidsongeschiktheid','uitkering'],bron:''},
 {id:'hnx-082',thema:'hypotheek-normen',vraag:'Hoe toets je inkomen uit een stamrechtuitkering?',antwoord:`Stamrechtuitkeringen zijn vaak tijdelijk. Ze tellen alleen mee voor zover de looptijd voldoende zeker is. Kijk naar het inkomen na de laatste termijn. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['stamrecht','uitkering','looptijd'],bron:''},
 {id:'hnx-083',thema:'hypotheek-normen',vraag:'Welke opties zijn er bij een klant met veel vermogen maar weinig inkomen?',antwoord:`Vermogen verhoogt het toetsinkomen in de regel niet. Een gebruikelijke route is een hogere eigen inbreng, zodat de lening lager wordt. Sommige geldverstrekkers kennen maatwerk waarbij vermogen wordt meegewogen. Controleer de voorwaarden en leg de afweging vast.
B:`,tags:['vermogen','eigen inbreng','maatwerk'],bron:''},
 {id:'hnx-084',thema:'hypotheek-normen',vraag:'Telt een jaarlijkse schenking van ouders mee als inkomen?',antwoord:`Nee, een schenking is geen inkomen en is niet afdwingbaar. Een eenmalige schenking kan wel eigen middelen opleveren voor de aankoop. Leg de schenking vast met een overeenkomst en bankafschriften. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['schenking','eigen middelen','inkomen'],bron:''},
 {id:'hnx-085',thema:'hypotheek-normen',vraag:'Hoe weeg je een onderhandse lening van familie mee?',antwoord:`Een familielening voor de woning is een tweede lening naast de hypotheek. Geldverstrekkers nemen de lasten mee en vragen vaak een achterstelling. Voor renteaftrek moet ook deze lening aan de fiscale eisen voldoen, zoals de aflossingseis. Controleer de voorwaarden en leg de afspraken vast.`,tags:['familielening','achterstelling','aflossingseis'],bron:'Wet IB 2001'},
 {id:'hnx-086',thema:'hypotheek-normen',vraag:'Hoe ga je om met een rekening-courantschuld van een DGA aan de bv?',antwoord:`Een rekening-courantschuld is een verplichting van de DGA aan de eigen bv. Geldverstrekkers kunnen die meewegen in de beoordeling. Bij hoge schulden kan ook de fiscale regeling voor excessief lenen bij de eigen vennootschap relevant zijn. Controleer de voorwaarden en laat de fiscale gevolgen beoordelen.
B:`,tags:['dga','rekening-courant','verplichtingen'],bron:''},
 {id:'hnx-087',thema:'hypotheek-normen',vraag:'Waar let je op als een DGA de woning financiert met een lening van de eigen bv?',antwoord:`Een lening van de eigen bv kan een eigenwoningschuld zijn als aan de fiscale eisen is voldaan. Denk aan de aflossingseis, een zakelijke rente en schriftelijke vastlegging. Combineer je dit met een bancaire hypotheek, dan neemt de geldverstrekker de lasten mee. Leg de afspraken vast in het dossier.`,tags:['dga','eigen bv','eigenwoningschuld'],bron:'Wet IB 2001'},
 {id:'hnx-088',thema:'hypotheek-normen',vraag:'Welke ondernemersstukken controleer je op onderlinge consistentie?',antwoord:`Leg de stukken naast elkaar:
- jaarcijfers en IB-aangiften
- aanslagen inkomstenbelasting
- uittreksel van de Kamer van Koophandel
- bankafschriften met privéopnamen
Verschillen tussen deze stukken moeten verklaarbaar zijn. Leg de verklaring vast in het dossier.
B:`,tags:['ondernemer','documenten','controle'],bron:''},
 {id:'hnx-089',thema:'hypotheek-normen',vraag:'Telt inkomen uit beleggen of handel in crypto mee?',antwoord:`Beleggingsresultaten zijn onzeker en tellen in de regel niet mee als toetsinkomen. Dat geldt ook voor handel in crypto. Is het een onderneming, dan gelden de eisen voor ondernemers. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['beleggen','crypto','toetsinkomen'],bron:''},
 {id:'hnx-090',thema:'hypotheek-normen',vraag:'Hoe toets je inkomen uit seizoenswerk?',antwoord:`Seizoenswerk geeft een wisselend inkomen over het jaar. Bij loondienst beoordelen geldverstrekkers dit vaak via IBL of als flexibel inkomen. Bij ondernemers kijk je naar de jaarcijfers over meerdere jaren. Leg vast hoe het jaarinkomen is bepaald.
B:`,tags:['seizoenswerk','flexibel inkomen','ibl'],bron:''},
 {id:'hnx-091',thema:'hypotheek-normen',vraag:'Hoe beoordeel je een expat met een tijdelijke uitzending naar Nederland?',antwoord:`Bij een tijdelijke uitzending is de duur van het verblijf en het contract onzeker. Geldverstrekkers kijken naar het contract, de verblijfsstatus en de verwachte verblijfsduur. Sommige geldverstrekkers hebben hiervoor aparte voorwaarden. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['expat','uitzending','acceptatie'],bron:''},
 {id:'hnx-092',thema:'hypotheek-normen',vraag:'Speelt de verblijfsstatus een rol bij de acceptatie?',antwoord:`Ja, geldverstrekkers stellen eisen aan de verblijfsstatus van aanvragers zonder Nederlandse of EU-nationaliteit. Een tijdelijke verblijfsvergunning kan beperkingen geven. De eisen verschillen per geldverstrekker. Leg de verblijfsdocumenten vast in het dossier.
B:`,tags:['verblijfsstatus','acceptatie','identiteit'],bron:''},
 {id:'hnx-093',thema:'hypotheek-normen',vraag:'Hoe beoordeel je een ondernemer die net een grote investering heeft gedaan?',antwoord:`Afschrijvingen en financieringslasten drukken de winst in de jaren na een investering. Een rekenexpert kan beoordelen of het inkomen daardoor tijdelijk lager is. Kijk ook naar de liquiditeit van de onderneming. Leg de beoordeling vast in het dossier.
B:`,tags:['investering','afschrijving','ondernemer'],bron:''},
 {id:'hnx-094',thema:'hypotheek-normen',vraag:'Hoe wordt een agrarisch ondernemer beoordeeld?',antwoord:`Agrarische ondernemers hebben vaak een woning die bij het bedrijf hoort. De financiering van zo een woning loopt vaak via een gespecialiseerde of zakelijke route. Voor het inkomen gelden de regels voor ondernemers. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['agrarisch','ondernemer','bedrijfswoning'],bron:''},
 {id:'hnx-095',thema:'hypotheek-normen',vraag:'Hoe ga je om met een woning die deels zakelijk wordt gebruikt?',antwoord:`Fiscaal is alleen het deel dat als eigen woning dient eigenwoningschuld. Geldverstrekkers stellen eisen aan de omvang en aard van het zakelijke gebruik. Een praktijk aan huis kan de waarde en courantheid beïnvloeden. Controleer de voorwaarden en leg de verdeling vast.`,tags:['zakelijk gebruik','eigen woning','praktijk aan huis'],bron:'Wet IB 2001'},
 {id:'hnx-096',thema:'hypotheek-normen',vraag:'Tellen inkomsten uit kortdurende verhuur via een platform mee?',antwoord:`Inkomsten uit kortdurende verhuur zijn wisselend en vaak niet zeker genoeg. Ze tellen daarom in de regel niet mee in het toetsinkomen. Daarnaast is verhuur van de eigen woning vaak alleen met toestemming van de geldverstrekker toegestaan. Controleer de voorwaarden en de lokale regels.
B:`,tags:['kortdurende verhuur','toestemming','toetsinkomen'],bron:''},
 {id:'hnx-097',thema:'hypotheek-normen',vraag:'Hoe beoordeel je een ondernemer met een openstaande belastingschuld?',antwoord:`Een belastingschuld is een verplichting en kan wijzen op een liquiditeitsprobleem. Breng de schuld en een eventuele betalingsregeling in kaart. Neem de lasten mee in de beoordeling. Leg de beoordeling vast in het dossier.
B:`,tags:['belastingschuld','ondernemer','verplichtingen'],bron:''},
 {id:'hnx-098',thema:'hypotheek-normen',vraag:'Hoe toets je een zzp-er die terugkeert naar loondienst?',antwoord:`Het nieuwe dienstverband is leidend voor het toetsinkomen. Daarvoor gelden de gewone eisen voor loondienst, inclusief proeftijd en contractduur. De ondernemershistorie is dan minder relevant. Let wel op eventuele schulden of verplichtingen uit de onderneming.
B:`,tags:['zzp','loondienst','overstap'],bron:''},
 {id:'hnx-099',thema:'hypotheek-normen',vraag:'Welke inkomensposten veranderen bij de toets na een scheiding?',antwoord:`Na een scheiding toets je alleen het eigen inkomen van de aanvrager. Ontvangen partneralimentatie kan meetellen en betaalde partneralimentatie verlaagt het toetsinkomen. Voor een alleenstaande geldt de verhoging van het toetsinkomen. Leg het convenant en de berekening vast in het dossier.`,tags:['scheiding','alimentatie','alleenstaanden'],bron:'Trhk'},
 {id:'hnx-100',thema:'hypotheek-normen',vraag:'Wat zijn veelgemaakte fouten bij ondernemersinkomen?',antwoord:`Veel voorkomende fouten zijn:
- eenmalige baten niet uit de winst halen
- een prognose gebruiken als gerealiseerd inkomen
- privéopnamen en liquiditeit niet bekijken
- de inkomensverklaring niet naast de aangiften leggen
Controleer de cijfers altijd zelf. Leg de controle vast in het dossier.
B:`,tags:['fouten','ondernemer','controle'],bron:''},
 {id:'hnx-101',thema:'hypotheek-normen',vraag:'Waarom rekent de toets met bruto lasten en niet met netto lasten?',antwoord:`De financieringslastpercentages houden al rekening met belasting en renteaftrek. Daarom reken je in de toets met bruto rente en aflossing. Wie zelf netto lasten in de toets stopt, rekent het fiscale voordeel dubbel. Netto lasten zijn wel nuttig voor het gesprek over betaalbaarheid.`,tags:['bruto lasten','netto lasten','financieringslast'],bron:'Trhk'},
 {id:'hnx-102',thema:'hypotheek-normen',vraag:'Welke stappen zet je van maximale jaarlast naar maximale hypotheek?',antwoord:`Een rekenvoorbeeld zonder actuele cijfers:
- bepaal het toetsinkomen en de toetsrente
- lees het financieringslastpercentage af en bereken de maximale bruto jaarlast
- deel door twaalf voor de maximale bruto maandlast
- reken die maandlast om naar een leenbedrag met een annuïteit over 360 maanden tegen de toetsrente
Trek daarna de lasten van verplichtingen af zoals de geldverstrekker voorschrijft. Leg elke stap vast.`,tags:['rekenvoorbeeld','annuiteit','maximale hypotheek'],bron:'Trhk'},
 {id:'hnx-103',thema:'hypotheek-normen',vraag:'Hoe werken toetsrente en financieringslastpercentage op elkaar in?',antwoord:`In de tabellen stijgt het percentage bij een hogere rente, omdat een groter deel van de last aftrekbare rente is. Tegelijk kost een hogere rente meer per geleende euro. Per saldo daalt de maximale hypotheek meestal bij een hogere toetsrente. Reken daarom altijd met de juiste combinatie van rente en tabel.`,tags:['toetsrente','financieringslast','rekenmodel'],bron:'Trhk'},
 {id:'hnx-104',thema:'hypotheek-normen',vraag:'Welke toetsrente geldt bij een variabele rente?',antwoord:`Een variabele rente valt onder een rentevaste periode korter dan 10 jaar. Je toetst dan met minimaal de toetsrente die de AFM per kwartaal vaststelt. Is de werkelijke rente hoger, dan toets je met de werkelijke rente. Leg het gebruikte percentage vast.`,tags:['variabele rente','toetsrente','afm'],bron:'Trhk'},
 {id:'hnx-105',thema:'hypotheek-normen',vraag:'Toets je met de rente vóór of na een rentekorting?',antwoord:`Uitgangspunt is de rente die voor de rentevaste periode wordt overeengekomen. Een korting die kan vervallen, bijvoorbeeld bij het opzeggen van een betaalrekening, geeft minder zekerheid. Geldverstrekkers verwerken kortingen verschillend in de toets. Controleer de werkwijze en leg vast met welke rente is gerekend.
B:`,tags:['rentekorting','toetsrente','offerte'],bron:''},
 {id:'hnx-106',thema:'hypotheek-normen',vraag:'Welke toetsrente geldt als de aanvraag rond een kwartaalwisseling loopt?',antwoord:`De minimale toetsrente van de AFM geldt per kwartaal. Rond een wisseling kan het moment van toetsen dus verschil maken. Bepaal welk moment de geldverstrekker hanteert, bijvoorbeeld de aanvraag of de offerte. Leg de gebruikte toetsrente en de datum vast.`,tags:['toetsrente','kwartaal','timing'],bron:'AFM'},
 {id:'hnx-107',thema:'hypotheek-normen',vraag:'Hoe toets je een aflossingsvrij deel dat onder het overgangsrecht valt?',antwoord:`Ook een aflossingsvrij deel wordt getoetst op basis van een annuïteit over 30 jaar. Valt het deel onder het fiscale overgangsrecht, dan is de rente aftrekbaar en gebruik je de gewone tabel. Controleer daarvoor de fiscale historie van de schuld. Leg vast op welke grond het deel aftrekbaar is.`,tags:['aflossingsvrij','overgangsrecht','tabelkeuze'],bron:'Wet IB 2001'},
 {id:'hnx-108',thema:'hypotheek-normen',vraag:'Wat is de marktwaarde voor de LTV-toets?',antwoord:`De LTV-toets gaat uit van de marktwaarde van de woning, meestal vastgesteld met een taxatierapport. De koopsom is niet automatisch de marktwaarde. Sommige geldverstrekkers gaan uit van de laagste van koopsom en marktwaarde. Controleer de voorwaarden van de geldverstrekker.`,tags:['marktwaarde','ltv','taxatie'],bron:'Trhk'},
 {id:'hnx-109',thema:'hypotheek-normen',vraag:'Wat als de taxatiewaarde lager uitvalt dan de koopsom?',antwoord:`De maximale lening daalt mee met de lagere marktwaarde. De klant heeft dan meer eigen middelen nodig. Bespreek dit tijdig, zeker als een financieringsvoorbehoud afloopt. Leg het gesprek en de gevolgen vast in het dossier.
B:`,tags:['taxatie','ltv','eigen middelen'],bron:''},
 {id:'hnx-110',thema:'hypotheek-normen',vraag:'Kan een taxatiewaarde boven de koopsom extra leenruimte geven?',antwoord:`Op grond van de Trhk is de marktwaarde de grens, niet de koopsom. Veel geldverstrekkers gaan bij aankoop toch uit van de laagste van beide. Het hangt dus af van het beleid van de geldverstrekker. Controleer de voorwaarden en leg vast welke waarde is gebruikt.`,tags:['taxatie','koopsom','ltv'],bron:'Trhk'},
 {id:'hnx-111',thema:'hypotheek-normen',vraag:'Hoe bepaal je de marktwaarde bij nieuwbouw?',antwoord:`Bij nieuwbouw gaan geldverstrekkers vaak uit van de koop- en aanneemsom, eventueel aangevuld met meerwerk. Soms vragen ze een taxatie op basis van tekening en bestek. Welke posten meetellen, verschilt per geldverstrekker. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['nieuwbouw','marktwaarde','meerwerk'],bron:''},
 {id:'hnx-112',thema:'hypotheek-normen',vraag:'Hoe telt een verbouwing mee in de LTV-toets?',antwoord:`Bij een verbouwing kan de geldverstrekker uitgaan van de marktwaarde na verbouwing. Die wordt meestal vastgesteld met een taxatie op basis van de plannen. Het verbouwingsbedrag gaat dan vaak in een bouwdepot. Controleer de voorwaarden en leg de begroting vast.
B:`,tags:['verbouwing','marktwaarde','bouwdepot'],bron:''},
 {id:'hnx-113',thema:'hypotheek-normen',vraag:'Hoe beïnvloedt erfpacht de waarde en de toets?',antwoord:`Bij erfpacht is de waarde van de woning vaak lager dan bij vol eigendom. De canon is een terugkerende woonlast. Geldverstrekkers stellen eisen aan de erfpachtvoorwaarden en de resterende looptijd. Controleer de voorwaarden en leg de erfpachtvoorwaarden vast.
B:`,tags:['erfpacht','canon','marktwaarde'],bron:''},
 {id:'hnx-114',thema:'hypotheek-normen',vraag:'Kan de afkoop van erfpacht worden meegefinancierd?',antwoord:`Dat is mogelijk als de geldverstrekker dat toestaat en de lening binnen de normen blijft. Fiscaal kan de schuld voor afkoop van erfpacht bij de eigen woning onder de eigenwoningschuld vallen, mits aan de voorwaarden is voldaan. Na afkoop vervalt de canon als woonlast. Laat de fiscale positie controleren en leg die vast.`,tags:['erfpacht','afkoop','eigenwoningschuld'],bron:'Wet IB 2001'},
 {id:'hnx-115',thema:'hypotheek-normen',vraag:'Telt de VvE-bijdrage mee in de toets?',antwoord:`De VvE-bijdrage is geen onderdeel van de financieringslastpercentages. Het is wel een vaste woonlast die de betaalbaarheid raakt. Sommige geldverstrekkers kijken ook naar de reserves en het onderhoudsplan van de VvE. Neem de bijdrage mee in het betaalbaarheidsgesprek.
B:`,tags:['vve','woonlasten','betaalbaarheid'],bron:''},
 {id:'hnx-116',thema:'hypotheek-normen',vraag:'Mag een bouwdepot voor een gewone verbouwing boven de LTV-grens uitkomen?',antwoord:`Nee, alleen voor energiebesparende voorzieningen staat de Trhk overschrijding van de LTV-grens toe. Een gewone verbouwing moet passen binnen de marktwaarde na verbouwing. Splits de begroting daarom in verduurzaming en overige verbouwing. Leg de splitsing vast in het dossier.`,tags:['bouwdepot','ltv','verbouwing'],bron:'Trhk'},
 {id:'hnx-117',thema:'hypotheek-normen',vraag:'Kun je labelruimte bij aankoop combineren met verduurzamingsruimte?',antwoord:`De systematiek kent twee aparte bedragen: een bedrag op basis van het energielabel bij aankoop en een bedrag voor verduurzamende maatregelen. Voor het tweede bedrag geldt een bestedingseis. Hoe een geldverstrekker beide bedragen combineert, verschilt. Controleer de voorwaarden van de geldverstrekker.`,tags:['energielabel','verduurzaming','leenruimte'],bron:'Nibud Advies hypotheeknormen 2026'},
 {id:'hnx-118',thema:'hypotheek-normen',vraag:'Welke extra ruimte geldt bij aankoop van een woning met label D die wordt verduurzaamd?',antwoord:`Een rekenvoorbeeld op basis van de bedragen voor 2026:
- labelruimte bij aankoop voor label C of D: €5.000
- ruimte voor verduurzaming bij label C of D: maximaal €15.000, te besteden aan maatregelen
Of de geldverstrekker beide bedragen toekent, hangt af van het beleid. Controleer de voorwaarden en leg de offerte van de maatregelen vast.`,tags:['rekenvoorbeeld','label d','verduurzaming'],bron:'Nibud Advies hypotheeknormen 2026'},
 {id:'hnx-119',thema:'hypotheek-normen',vraag:'Welke extra ruimte geldt bij een woning zonder geregistreerd energielabel?',antwoord:`Zonder geldig label geldt bij aankoop geen extra labelruimte. Voor verduurzaming geldt de categorie onbekend label, met maximaal €10.000 voor maatregelen. Laat de verkoper zo nodig alsnog een label registreren. Leg de labelsituatie vast in het dossier.`,tags:['energielabel','onbekend label','verduurzaming'],bron:'Nibud Advies hypotheeknormen 2026'},
 {id:'hnx-120',thema:'hypotheek-normen',vraag:'Wat is nodig voor de hogere leenruimte bij label A++++ met garantie?',antwoord:`Voor label A++++ geldt €30.000 en met een energieprestatiegarantie €40.000. Voor het hogere bedrag moet de garantie aantoonbaar zijn. Vraag het garantiedocument op en controleer de voorwaarden ervan. Leg het label en de garantie vast in het dossier.`,tags:['a++++','energieprestatiegarantie','leenruimte'],bron:'Nibud Advies hypotheeknormen 2026'},
 {id:'hnx-121',thema:'hypotheek-normen',vraag:'Welk label gebruik je bij nieuwbouw die nog niet is opgeleverd?',antwoord:`Bij nieuwbouw is het definitieve label vaak pas bij oplevering geregistreerd. Geldverstrekkers accepteren dan vaak een verwacht label op basis van de energieprestatieberekening. Of dat volstaat, verschilt per geldverstrekker. Controleer de voorwaarden en leg het gebruikte stuk vast.
B:`,tags:['nieuwbouw','energielabel','oplevering'],bron:''},
 {id:'hnx-122',thema:'hypotheek-normen',vraag:'Geldt voor de labelruimte bij aankoop ook een bestedingseis?',antwoord:`De labelruimte bij aankoop hangt af van het label van de woning en is niet bestemd voor specifieke maatregelen. De ruimte voor verduurzamende maatregelen moet wel aan maatregelen worden besteed. Haal deze twee niet door elkaar. Controleer de voorwaarden van de geldverstrekker.`,tags:['labelruimte','bestedingseis','verduurzaming'],bron:'Nibud Advies hypotheeknormen 2026'},
 {id:'hnx-123',thema:'hypotheek-normen',vraag:'Hoe onderbouw je de verduurzamingsmaatregelen in het dossier?',antwoord:`Gebruikelijke stukken zijn:
- een offerte of specificatie van de maatregelen
- eventueel een maatwerkadvies of energieadvies
- facturen bij uitbetaling uit het bouwdepot
Controleer welke stukken de geldverstrekker vraagt. Leg de stukken en de besteding vast.
B:`,tags:['verduurzaming','documentatie','bouwdepot'],bron:''},
 {id:'hnx-124',thema:'hypotheek-normen',vraag:'Welk label geldt als het nieuwe label na verduurzaming nog niet is geregistreerd?',antwoord:`Voor de verduurzamingsruimte kijk je naar het label op het moment van de aanvraag. Een beter label na verduurzaming telt pas als het is geregistreerd. Wordt de woning vóór de aanvraag verduurzaamd, controleer dan de registratie in EP-Online. Leg vast welk label je hebt gebruikt.
B:`,tags:['energielabel','ep-online','verduurzaming'],bron:''},
 {id:'hnx-125',thema:'hypotheek-normen',vraag:'Wanneer is een aanvrager alleenstaand voor de toets?',antwoord:`Het gaat om een aanvrager die de lening zonder partner aangaat. Gaat een partner mee als aanvrager, ook zonder inkomen, dan is er geen sprake van een alleenstaande. Geldverstrekkers hanteren hierbij eigen definities. Leg de woonsituatie vast en controleer de voorwaarden.`,tags:['alleenstaanden','aanvrager','toetsinkomen'],bron:'Nibud Advies hypotheeknormen 2026'},
 {id:'hnx-126',thema:'hypotheek-normen',vraag:'Hoe toets je een verhoging van een bestaande hypotheek?',antwoord:`Bij een verhoging wordt de totale lening getoetst aan de normen. De bestaande delen behouden hun eigen rente, waarbij voor de toets per deel de juiste rente geldt. Ook de LTV wordt over de totale lening bepaald. Controleer de voorwaarden van de geldverstrekker.`,tags:['verhoging','toetsing','leningdelen'],bron:'Trhk'},
 {id:'hnx-127',thema:'hypotheek-normen',vraag:'Moet bij een verhoging ook de bestaande lening opnieuw worden getoetst?',antwoord:`Ja, de beoordeling gaat over de totale schuld na de verhoging. De geldverstrekker kijkt dus naar de lasten van alle leningdelen samen. Een klant die de bestaande lening nog draagt, voldoet daarmee niet automatisch voor de verhoging. Leg de berekening van de totale lening vast.`,tags:['verhoging','bestaande lening','toetsing'],bron:'Trhk'},
 {id:'hnx-128',thema:'hypotheek-normen',vraag:'Hoe toets je een tweede hypotheek bij een andere geldverstrekker?',antwoord:`De nieuwe geldverstrekker kijkt naar de totale lasten, inclusief de bestaande hypotheek. Ook de LTV wordt over alle leningen samen bepaald. De rangorde van de hypotheekrechten speelt een rol bij de acceptatie. Controleer de voorwaarden van beide geldverstrekkers.`,tags:['tweede hypotheek','rangorde','ltv'],bron:'Trhk'},
 {id:'hnx-129',thema:'hypotheek-normen',vraag:'Wat betekent een kortere werkelijke looptijd voor de betaalbaarheid?',antwoord:`De toets rekent met een annuïteit over 30 jaar. Kiest de klant een kortere looptijd, dan is de werkelijke maandlast hoger dan de toetslast. De norm zegt daar niets over. Beoordeel de werkelijke last en leg die afweging vast.`,tags:['looptijd','maandlast','zorgplicht'],bron:'Wft'},
 {id:'hnx-130',thema:'hypotheek-normen',vraag:'Waar let je op bij een lineaire hypotheek in de toets?',antwoord:`De toets gaat uit van een annuïtaire last over 30 jaar. Bij lineair aflossen is de werkelijke last in de eerste jaren hoger. Beoordeel of de klant die hogere beginlast kan dragen. Leg die afweging vast in het dossier.
B:`,tags:['lineair','toetslast','beginlast'],bron:''},
 {id:'hnx-131',thema:'hypotheek-normen',vraag:'Hoe ga je om met een renteopslag voor een hogere LTV-klasse?',antwoord:`Een opslag maakt deel uit van de werkelijke rente. Bij een rentevaste periode van 10 jaar of langer toets je met die werkelijke rente. Bij een kortere periode geldt de hoogste van de werkelijke rente en de AFM-toetsrente. Leg de gebruikte rente vast.`,tags:['renteopslag','ltv-klasse','toetsrente'],bron:'Trhk'},
 {id:'hnx-132',thema:'hypotheek-normen',vraag:'Hoe bepaal je welke leningdelen fiscaal aftrekbaar zijn voor de tabelkeuze?',antwoord:`Ga per deel na of het eigenwoningschuld is. Let op de aflossingseis, de bijleenregeling en eventueel overgangsrecht. Delen die niet aan de voorwaarden voldoen, vallen in box 3. Leg de fiscale onderbouwing per deel vast.`,tags:['eigenwoningschuld','box 3','tabelkeuze'],bron:'Wet IB 2001'},
 {id:'hnx-133',thema:'hypotheek-normen',vraag:'Hoe beïnvloedt een eigenwoningreserve de toets?',antwoord:`Brengt de klant de eigenwoningreserve niet in, dan is een deel van de nieuwe lening geen eigenwoningschuld. Dat deel valt in box 3 en de rente is niet aftrekbaar. Voor dat deel geldt in de toets de tabel voor niet-aftrekbare delen. Leg de berekening van de eigenwoningreserve vast.`,tags:['eigenwoningreserve','box 3','bijleenregeling'],bron:'Wet IB 2001'},
 {id:'hnx-134',thema:'hypotheek-normen',vraag:'Wanneer vervalt een eigenwoningreserve?',antwoord:`Een eigenwoningreserve vervalt drie jaar na het ontstaan ervan. Na die termijn hoeft de klant er bij een nieuwe aankoop geen rekening meer mee te houden. Controleer de datum van verkoop van de vorige woning. Leg die datum en de berekening vast in het dossier.`,tags:['eigenwoningreserve','termijn','bijleenregeling'],bron:'Wet IB 2001'},
 {id:'hnx-135',thema:'hypotheek-normen',vraag:'Wat betekent de restschuldregeling voor de financiering?',antwoord:`Rente op een restschuld die is ontstaan tussen 29 oktober 2012 en 31 december 2017 is maximaal 15 jaar aftrekbaar. Voor een restschuld van daarna geldt deze regeling niet. Bepaal voor de tabelkeuze of de rente op het restschulddeel aftrekbaar is. Of een restschuld kan worden meegefinancierd, verschilt per geldverstrekker.`,tags:['restschuld','renteaftrek','tabelkeuze'],bron:'Wet IB 2001'},
 {id:'hnx-136',thema:'hypotheek-normen',vraag:'Wat betekent de afbouw van de Wet Hillen voor de advisering?',antwoord:`De aftrek wegens geen of geringe eigenwoningschuld wordt sinds 2019 in 30 jaar afgebouwd. Dit raakt klanten met weinig of geen hypotheekschuld. Voor de normtoets is dit niet direct van belang. Neem het wel mee bij advies over extra aflossen en de netto lasten.`,tags:['wet hillen','aflossen','netto lasten'],bron:'Wet IB 2001'},
 {id:'hnx-137',thema:'hypotheek-normen',vraag:'Hoe ga je om met de oude woning die leeg staat en te koop staat?',antwoord:`Een leegstaande woning die te koop staat, kan maximaal drie jaar fiscaal eigen woning blijven. In die periode is de rente op beide leningen aftrekbaar. Geldverstrekkers toetsen of de klant de tijdelijke dubbele lasten kan dragen. Leg de verkoopstatus en de termijnen vast.`,tags:['oude woning','dubbele lasten','eigen woning'],bron:'Wet IB 2001'},
 {id:'hnx-138',thema:'hypotheek-normen',vraag:'Wat gebeurt er als de oude woning na drie jaar nog niet is verkocht?',antwoord:`Na die termijn is de oude woning fiscaal geen eigen woning meer. De woning en de schuld vallen dan in box 3 en de rente is niet meer aftrekbaar. De netto lasten stijgen daardoor. Bespreek dit scenario vooraf met de klant en leg het vast.`,tags:['oude woning','box 3','netto lasten'],bron:'Wet IB 2001'},
 {id:'hnx-139',thema:'hypotheek-normen',vraag:'Wat als de oude woning tijdelijk wordt verhuurd?',antwoord:`Een verhuurde woning staat niet leeg en voldoet dan niet aan de voorwaarde voor de fiscale regeling. Daarnaast is verhuur vaak alleen toegestaan met toestemming van de geldverstrekker. Bespreek de fiscale en contractuele gevolgen met de klant. Leg de afspraken vast in het dossier.`,tags:['verhuur','oude woning','toestemming'],bron:'Wet IB 2001'},
 {id:'hnx-140',thema:'hypotheek-normen',vraag:'Welke waardebepaling is nodig bij een verhoging van de hypotheek?',antwoord:`Voor een verhoging is een actuele waarde nodig om de LTV te bepalen. Dat kan een taxatierapport zijn of een andere waardebepaling die de geldverstrekker accepteert. Welke vorm volstaat, hangt vaak af van de hoogte van de LTV. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['waardebepaling','verhoging','ltv'],bron:''},
 {id:'hnx-141',thema:'hypotheek-normen',vraag:'Mag je een modelwaarde in plaats van een taxatie gebruiken?',antwoord:`Sommige geldverstrekkers accepteren een gevalideerde modelwaarde onder voorwaarden. Vaak geldt dat alleen bij een lagere LTV of bepaalde woningtypen. Bij aankoop is een volledige taxatie meestal nodig. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['modelwaarde','taxatie','waardebepaling'],bron:''},
 {id:'hnx-142',thema:'hypotheek-normen',vraag:'Hoe lang is een taxatierapport bruikbaar?',antwoord:`Geldverstrekkers stellen een maximale ouderdom aan taxatierapporten. Die termijn verschilt per geldverstrekker. Een verlopen rapport moet worden vernieuwd. Controleer de termijn al bij het plannen van de taxatie.
B:`,tags:['taxatierapport','ouderdom','waardebepaling'],bron:''},
 {id:'hnx-143',thema:'hypotheek-normen',vraag:'Wat doe je als de taxateur bijzonderheden meldt, zoals funderingsproblemen?',antwoord:`Bijzonderheden kunnen de acceptatie en de waarde beïnvloeden. De geldverstrekker kan nader onderzoek, een herstelplan of een bouwdepot vragen. Bespreek de gevolgen met de klant. Leg de bevindingen en de afspraken vast in het dossier.
B:`,tags:['taxatie','fundering','acceptatie'],bron:''},
 {id:'hnx-144',thema:'hypotheek-normen',vraag:'Hoe toets je de financiering van een recreatiewoning?',antwoord:`Een recreatiewoning is geen hoofdverblijf en dus fiscaal geen eigen woning. De rente is niet aftrekbaar, zodat de tabel voor niet-aftrekbare delen relevant is. Veel geldverstrekkers financieren recreatiewoningen niet of onder strengere voorwaarden. Controleer de voorwaarden van de geldverstrekker.`,tags:['recreatiewoning','box 3','acceptatie'],bron:'Wet IB 2001'},
 {id:'hnx-145',thema:'hypotheek-normen',vraag:'Hoe toets je een woning die een ouder koopt voor een kind?',antwoord:`Woont de ouder er niet zelf, dan is het voor de ouder geen eigen woning. De lening valt dan in box 3 en de rente is niet aftrekbaar. Daarnaast gaat het vaak om verhuur, waarvoor de geldverstrekker toestemming moet geven. Controleer de voorwaarden en leg de constructie vast.`,tags:['ouder','kind','box 3'],bron:'Wet IB 2001'},
 {id:'hnx-146',thema:'hypotheek-normen',vraag:'Tellen inkomsten uit kamerverhuur in de eigen woning mee?',antwoord:`Inkomsten uit kamerverhuur tellen in de regel niet mee als toetsinkomen. Verhuur kan bovendien toestemming van de geldverstrekker vereisen. Fiscaal kan een aparte regeling voor kamerverhuur gelden, afhankelijk van de voorwaarden. Controleer de voorwaarden en leg de afspraken vast.
B:`,tags:['kamerverhuur','toestemming','toetsinkomen'],bron:''},
 {id:'hnx-147',thema:'hypotheek-normen',vraag:'Hoe reken je het effect van een studieschuld door zonder actuele cijfers?',antwoord:`Een rekenvoorbeeld in stappen:
- vraag het wettelijke maandbedrag op bij DUO
- vermenigvuldig dit met de bruteringsfactor die hoort bij de toetsrente
- verlaag de maximale bruto maandlast met de uitkomst
- reken de resterende maandlast om naar een leenbedrag
Gebruik de factoren uit de actuele Trhk. Leg elke stap vast in het dossier.`,tags:['studieschuld','rekenvoorbeeld','bruteringsfactor'],bron:'Trhk'},
 {id:'hnx-148',thema:'hypotheek-normen',vraag:'Waarom verschilt de maximale hypotheek bij gelijk inkomen per geldverstrekker?',antwoord:`Oorzaken zijn onder meer:
- verschillende rente en dus toetsrente
- eigen strengere acceptatieregels
- verschillende weging van verplichtingen
- verschillende inkomensmethoden of waardebepalingen
Leg vast waarom je voor een bepaalde geldverstrekker kiest.
B:`,tags:['geldverstrekker','maximale hypotheek','verschillen'],bron:''},
 {id:'hnx-149',thema:'hypotheek-normen',vraag:'Hoe controleer je of een rekentool de juiste normen gebruikt?',antwoord:`Controleer het jaar van de gebruikte normtabellen en de toegepaste toetsrente. Kijk ook of de juiste tabel is gekozen, bijvoorbeeld voor AOW of niet-aftrekbare delen. Vergelijk de uitkomst met de berekening van de geldverstrekker. Leg de versie van de tool vast in het dossier.
B:`,tags:['rekentool','normen','controle'],bron:''},
 {id:'hnx-150',thema:'hypotheek-normen',vraag:'Wat zijn veelgemaakte fouten bij toetsrente en LTV?',antwoord:`Veel voorkomende fouten zijn:
- de toetsrente van een vorig kwartaal gebruiken
- bij een korte rentevaste periode de werkelijke rente gebruiken terwijl die lager is
- de koopsom gebruiken in plaats van de marktwaarde
- een gewone verbouwing boven de LTV-grens financieren
Controleer deze punten vóór het indienen. Leg de controle vast.
B:`,tags:['fouten','toetsrente','ltv'],bron:''},
 {id:'hnx-151',thema:'hypotheek-normen',vraag:'Hoe telt een private leasecontract mee bij de hypotheektoets?',antwoord:`Een private leasecontract is een vaste maandelijkse verplichting. Nieuwe contracten worden in de regel bij BKR geregistreerd. Geldverstrekkers nemen de leaseprijs mee als last, maar de weging verschilt. Controleer de voorwaarden van de geldverstrekker.`,tags:['private lease','bkr','verplichtingen'],bron:'BKR'},
 {id:'hnx-152',thema:'hypotheek-normen',vraag:'Wat doe je met een private leasecontract dat niet in BKR staat?',antwoord:`Ook een niet-geregistreerd contract is een verplichting. Vraag de klant actief naar leasecontracten en controleer de bankafschriften. Neem de maandlast mee in de beoordeling. Verzwijgen kan gevolgen hebben voor de acceptatie.
B:`,tags:['private lease','bkr','inventarisatie'],bron:''},
 {id:'hnx-153',thema:'hypotheek-normen',vraag:'Telt een zakelijke lease van een ondernemer mee als privéverplichting?',antwoord:`Een lease op naam van de onderneming is in de regel een zakelijke last. Die zit al in de winst die je voor het inkomen gebruikt. Staat de ondernemer privé garant of op eigen naam, dan kan het een privéverplichting zijn. Controleer de contracten en de voorwaarden van de geldverstrekker.
B:`,tags:['zakelijke lease','ondernemer','verplichtingen'],bron:''},
 {id:'hnx-154',thema:'hypotheek-normen',vraag:'Hoe ga je om met achteraf betalen en kleine betaalregelingen?',antwoord:`Kleine betaalregelingen staan niet altijd in BKR. Ze kunnen wel wijzen op krapte in het budget. Bekijk de bankafschriften en vraag de klant naar lopende regelingen. Neem structurele lasten mee in de beoordeling.
B:`,tags:['achteraf betalen','betaalregeling','betaalgedrag'],bron:''},
 {id:'hnx-155',thema:'hypotheek-normen',vraag:'Hoe telt een creditcard mee in de toets?',antwoord:`Een creditcard met kredietlimiet is een doorlopend krediet. Geldverstrekkers rekenen vaak met een vast deel van de limiet als maandlast, ook als de kaart maandelijks volledig wordt afgelost. De werkwijze verschilt per geldverstrekker. Controleer de BKR-registratie en de voorwaarden.`,tags:['creditcard','limiet','verplichtingen'],bron:'BKR'},
 {id:'hnx-156',thema:'hypotheek-normen',vraag:'Hoe ga je om met een roodstandfaciliteit op de betaalrekening?',antwoord:`Een roodstandfaciliteit is een vorm van krediet. Afhankelijk van de vorm kan die in BKR geregistreerd staan. Een geregistreerde faciliteit telt meestal mee als verplichting. Controleer de registratie en de voorwaarden van de geldverstrekker.`,tags:['roodstand','krediet','bkr'],bron:'BKR'},
 {id:'hnx-157',thema:'hypotheek-normen',vraag:'Telt een telefoonabonnement met toestel mee als verplichting?',antwoord:`Bij een abonnement met toestel kan het toestel als krediet zijn verstrekt. Zo een toestelkrediet kan in BKR geregistreerd staan. Geldverstrekkers gaan er verschillend mee om. Controleer de registratie en de voorwaarden van de geldverstrekker.`,tags:['toestelkrediet','bkr','verplichtingen'],bron:'BKR'},
 {id:'hnx-158',thema:'hypotheek-normen',vraag:'Hoe verwerk je een krediet dat vóór het passeren wordt afgelost?',antwoord:`Geldverstrekkers vragen meestal bewijs van aflossing en beëindiging vóór of bij het passeren. Een doorlopend krediet moet vaak ook worden opgezegd. Soms neemt de geldverstrekker dit op als voorwaarde in de offerte. Leg de afspraken en het bewijs vast in het dossier.
B:`,tags:['krediet','aflossing','passeren'],bron:''},
 {id:'hnx-159',thema:'hypotheek-normen',vraag:'Mag een consumptief krediet worden afgelost met de hypotheek?',antwoord:`Dat kan als de geldverstrekker het toestaat en de lening binnen de normen blijft. Het deel voor het krediet is geen eigenwoningschuld en valt in box 3. Bespreek of omzetten van kortlopend naar langlopend krediet in het belang van de klant is. Leg de afweging vast in het dossier.`,tags:['krediet','box 3','oversluiten'],bron:'Wet IB 2001'},
 {id:'hnx-160',thema:'hypotheek-normen',vraag:'Hoe ga je om met een borgstelling door de klant?',antwoord:`Een borgtocht is een voorwaardelijke verplichting. Wordt de borg aangesproken, dan kan dat de betaalbaarheid raken. Vraag de klant naar borgstellingen en de omvang daarvan. Controleer hoe de geldverstrekker dit beoordeelt en leg het vast.
B:`,tags:['borgtocht','verplichtingen','risico'],bron:''},
 {id:'hnx-161',thema:'hypotheek-normen',vraag:'Hoe telt een hypotheek op een andere woning mee?',antwoord:`De lasten van een andere hypotheek zijn een verplichting. Geldverstrekkers nemen die mee in de toets, eventueel verminderd met huurinkomsten volgens hun beleid. De rente op een niet-eigen woning is niet aftrekbaar. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['andere woning','verplichtingen','verhuur'],bron:''},
 {id:'hnx-162',thema:'hypotheek-normen',vraag:'Telt een studieschuld mee als de klant nog niet aflost?',antwoord:`Ook tijdens een periode zonder aflossing telt de studieschuld mee. De klant moet later gaan aflossen en die last hoort in de toets. Vraag het overzicht van DUO op voor het juiste bedrag. Controleer de voorwaarden van de geldverstrekker.`,tags:['studieschuld','aanloopfase','duo'],bron:'Trhk'},
 {id:'hnx-163',thema:'hypotheek-normen',vraag:'Hoe toon je aan dat een studieschuld volledig is afgelost?',antwoord:`Vraag een actueel overzicht van DUO met het resterende saldo op. Een saldo van nul laat zien dat er geen schuld meer is. Een bankafschrift van de laatste betaling is aanvullend bewijs. Leg het overzicht vast in het dossier.
B:`,tags:['studieschuld','aflossing','duo'],bron:''},
 {id:'hnx-164',thema:'hypotheek-normen',vraag:'Hoe voorkom je dat een studieschuld wordt gemist?',antwoord:`Een studieschuld bij DUO staat niet in BKR. De adviseur moet er dus actief naar vragen. Bankafschriften met betalingen aan DUO zijn een signaal. Laat de klant een DUO-overzicht aanleveren of verklaren dat er geen schuld is.
B:`,tags:['studieschuld','bkr','inventarisatie'],bron:''},
 {id:'hnx-165',thema:'hypotheek-normen',vraag:'Telt een energiebespaarlening of financiering via een leverancier mee?',antwoord:`Een lening voor bijvoorbeeld zonnepanelen of een warmtepomp is een verplichting. Afhankelijk van de vorm kan die in BKR geregistreerd staan. Geldverstrekkers nemen de last in de regel mee. Controleer de registratie en de voorwaarden van de geldverstrekker.
B:`,tags:['energiebespaarlening','verplichtingen','bkr'],bron:''},
 {id:'hnx-166',thema:'hypotheek-normen',vraag:'Telt de erfpachtcanon mee als last?',antwoord:`De erfpachtcanon is een terugkerende woonlast. Geldverstrekkers nemen de canon in de regel mee bij het bepalen van de leenruimte. De precieze verwerking verschilt. Controleer de voorwaarden en leg de erfpachtakte vast.
B:`,tags:['erfpacht','canon','woonlasten'],bron:''},
 {id:'hnx-167',thema:'hypotheek-normen',vraag:'Hoe weeg je een BKR-achterstand die inmiddels is hersteld?',antwoord:`Een herstelde achterstand blijft na herstel nog een periode zichtbaar. Geldverstrekkers kijken naar de oorzaak, de omvang en de tijd sinds het herstel. Sommige accepteren de aanvraag met een goede uitleg. Leg de uitleg van de klant en de beoordeling vast.`,tags:['bkr','herstel','acceptatie'],bron:'BKR'},
 {id:'hnx-168',thema:'hypotheek-normen',vraag:'Hoe breng je verplichtingen in kaart die niet in BKR staan?',antwoord:`Denk aan:
- studieschuld bij DUO
- partneralimentatie en kinderalimentatie
- leningen van familie of werkgever
- betalingsregelingen met de Belastingdienst of andere schuldeisers
Vraag hier actief naar en controleer de bankafschriften. Laat de klant de opgave bevestigen.
B:`,tags:['verplichtingen','inventarisatie','bkr'],bron:''},
 {id:'hnx-169',thema:'hypotheek-normen',vraag:'Waarom vragen geldverstrekkers recente bankafschriften?',antwoord:`Bankafschriften laten de ontvangst van inkomen en de vaste lasten zien. Ze maken ook verplichtingen zichtbaar die niet in BKR staan. Daarnaast tonen ze het betaalgedrag. Controleer de afschriften zelf voordat je ze indient.
B:`,tags:['bankafschriften','controle','verplichtingen'],bron:''},
 {id:'hnx-170',thema:'hypotheek-normen',vraag:'Kan een klant met een afgerond schuldsaneringstraject een hypotheek krijgen?',antwoord:`Een afgerond traject blijft nog enige tijd zichtbaar in BKR. Veel geldverstrekkers zijn terughoudend zolang de registratie zichtbaar is. Het beleid verschilt sterk. Controleer de voorwaarden en leg de beoordeling vast.
B:`,tags:['schuldsanering','wsnp','bkr'],bron:''},
 {id:'hnx-171',thema:'hypotheek-normen',vraag:'Wat betekent beschermingsbewind voor een hypotheekaanvraag?',antwoord:`Bij beschermingsbewind beheert een bewindvoerder het vermogen van de klant. Voor het aangaan van een hypotheek is dan medewerking van de bewindvoerder nodig. Veel geldverstrekkers accepteren een aanvraag onder bewind niet. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['bewind','bewindvoerder','acceptatie'],bron:''},
 {id:'hnx-172',thema:'hypotheek-normen',vraag:'Tellen verplichtingen van een partner die niet meetekent mee?',antwoord:`Formeel toetst de geldverstrekker de aanvragers. Verplichtingen van een samenwonende partner raken wel het huishoudbudget. De zorgplicht vraagt dat je dit meeweegt. Leg de afweging vast in het dossier.`,tags:['partner','verplichtingen','zorgplicht'],bron:'Wft'},
 {id:'hnx-173',thema:'hypotheek-normen',vraag:'Hoe ga je om met partneralimentatie waarvan een wijziging wordt verwacht?',antwoord:`Uitgangspunt is de alimentatie zoals die nu is vastgelegd. Een verwachte wijziging telt pas als die is vastgelegd in een convenant of uitspraak. Bespreek met de klant wat er gebeurt als de wijziging uitblijft. Leg de afweging vast in het dossier.
B:`,tags:['partneralimentatie','wijziging','convenant'],bron:''},
 {id:'hnx-174',thema:'hypotheek-normen',vraag:'Telt partneralimentatie mee die binnenkort eindigt?',antwoord:`Ook dan is de huidige verplichting het uitgangspunt. Geldverstrekkers kunnen regels hebben voor een verplichting die binnen korte tijd eindigt. Leg de einddatum vast met het convenant of de uitspraak. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['partneralimentatie','einddatum','verplichtingen'],bron:''},
 {id:'hnx-175',thema:'hypotheek-normen',vraag:'Hoe beoordeelt een geldverstrekker een restschuld bij verhuizing?',antwoord:`Een restschuld vergroot de totale lening ten opzichte van de nieuwe woning. Of die kan worden meegefinancierd, hangt af van het beleid van de geldverstrekker en de normen. Ook de fiscale status van de restschuld speelt een rol. Controleer de voorwaarden en leg de afweging vast.
B:`,tags:['restschuld','verhuizing','acceptatie'],bron:''},
 {id:'hnx-176',thema:'hypotheek-normen',vraag:'Welke lasten vallen buiten de normtoets maar wel binnen de betaalbaarheid?',antwoord:`Voorbeelden zijn:
- VvE-bijdrage en onderhoud
- kinderopvang en zorgkosten
- autokosten
- premies voor verzekeringen
Neem deze mee in het gesprek over betaalbaarheid. Leg de afweging vast in het dossier.`,tags:['woonlasten','betaalbaarheid','zorgplicht'],bron:'Wft'},
 {id:'hnx-177',thema:'hypotheek-normen',vraag:'Wat is het verschil tussen de normtoets en een budgetanalyse?',antwoord:`De normtoets bepaalt de maximale lening op basis van gemiddelde uitgaven. Een budgetanalyse kijkt naar de werkelijke uitgaven van het huishouden. Bij hoge vaste lasten kan de budgetanalyse een lager verantwoord bedrag geven. Leg de uitkomst van beide vast.
B:`,tags:['budgetanalyse','normtoets','betaalbaarheid'],bron:''},
 {id:'hnx-178',thema:'hypotheek-normen',vraag:'Welke identiteitscontroles horen bij de acceptatie?',antwoord:`Controleer een geldig identiteitsbewijs en de gegevens in de aanvraag. Geldverstrekkers controleren daarnaast onder meer adres en rekeningnummer. Inconsistenties kunnen leiden tot vertraging of afwijzing. Leg je eigen controle vast in het dossier.`,tags:['identiteit','acceptatie','controle'],bron:'Wwft'},
 {id:'hnx-179',thema:'hypotheek-normen',vraag:'Waarom is de timing van het financieringsvoorbehoud belangrijk?',antwoord:`Na de datum van het voorbehoud kan de klant de koop meestal niet meer kosteloos ontbinden. De acceptatie moet daarom op tijd rond zijn. Plan de aanvraag, de taxatie en de stukken met die datum in gedachten. Leg de datum vast in het dossier.
B:`,tags:['financieringsvoorbehoud','timing','koopovereenkomst'],bron:''},
 {id:'hnx-180',thema:'hypotheek-normen',vraag:'Wat doe je als de acceptatie niet rond is vóór het einde van het voorbehoud?',antwoord:`Bespreek met de klant of uitstel via de verkoper mogelijk is. Anders moet de klant kiezen tussen ontbinden en het risico van doorgaan zonder zekerheid. Wijs de klant op de mogelijke gevolgen, zoals een boete. Leg de keuze en het advies vast.
B:`,tags:['financieringsvoorbehoud','uitstel','ontbinding'],bron:''},
 {id:'hnx-181',thema:'hypotheek-normen',vraag:'Waarom kan een aanvraag worden afgewezen terwijl die binnen de normen valt?',antwoord:`De Trhk geeft maximale normen. De geldverstrekker beoordeelt daarnaast onder meer BKR, onderpand, stukken en fraude-indicaties. Op elk van die punten kan het eigen beleid strenger zijn. Vraag naar de reden van afwijzing en leg die vast.`,tags:['afwijzing','acceptatie','beleid'],bron:'Trhk'},
 {id:'hnx-182',thema:'hypotheek-normen',vraag:'Hoe ga je om met een nieuwe aanvraag na een afwijzing?',antwoord:`Een nieuwe aanvraag bij een andere geldverstrekker is mogelijk. Gebruik dezelfde, juiste gegevens en pas niets aan om een afwijzing te omzeilen. Vermeld een eerdere afwijzing als daarnaar wordt gevraagd. Leg de reden van de afwijzing en de vervolgstap vast.
B:`,tags:['afwijzing','nieuwe aanvraag','integriteit'],bron:''},
 {id:'hnx-183',thema:'hypotheek-normen',vraag:'Wat zijn de risicos van het aanpassen van gegevens om binnen de normen te passen?',antwoord:`Het aanpassen van gegevens is fraude. Het kan leiden tot afwijzing, opeising van de lening en registratie in fraudesystemen. Voor de adviseur staat de vakbekwaamheid en betrouwbaarheid op het spel. Weiger medewerking en leg dat vast.`,tags:['fraude','integriteit','gevolgen'],bron:'Wft'},
 {id:'hnx-184',thema:'hypotheek-normen',vraag:'Welke rol speelt het onderpand naast de LTV-toets?',antwoord:`De geldverstrekker kijkt ook naar de courantheid en de staat van de woning. Bijzondere woningtypen of gebreken kunnen tot extra voorwaarden of afwijzing leiden. Het taxatierapport is hierbij de belangrijkste bron. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['onderpand','courantheid','taxatie'],bron:''},
 {id:'hnx-185',thema:'hypotheek-normen',vraag:'Hoe kijken geldverstrekkers naar een woning met een bijzondere bestemming?',antwoord:`De bestemming in het omgevingsplan moet passen bij permanente bewoning. Een recreatieve, agrarische of bedrijfsbestemming kan de acceptatie beperken. Het taxatierapport vermeldt de bestemming meestal. Controleer de voorwaarden en leg de bestemming vast.
B:`,tags:['bestemming','omgevingsplan','acceptatie'],bron:''},
 {id:'hnx-186',thema:'hypotheek-normen',vraag:'Hoe verhouden de NHG-normen zich tot de Trhk?',antwoord:`NHG kent eigen Voorwaarden & Normen. Die sluiten grotendeels aan bij de Trhk, maar bevatten aanvullende eisen. Daarnaast geldt een kostengrens; het actuele bedrag staat op de website van NHG. Toets een NHG-lening altijd aan beide.`,tags:['nhg','trhk','normen'],bron:'Voorwaarden & Normen NHG'},
 {id:'hnx-187',thema:'hypotheek-normen',vraag:'Kan een lening binnen de Trhk toch niet voldoen aan de NHG-normen?',antwoord:`Ja, omdat NHG aanvullende eisen stelt. Denk aan de kostengrens en eigen regels voor inkomen en verplichtingen. De lening kan dan wel zonder NHG passen. Bespreek de gevolgen van het ontbreken van NHG met de klant.`,tags:['nhg','kostengrens','acceptatie'],bron:'Voorwaarden & Normen NHG'},
 {id:'hnx-188',thema:'hypotheek-normen',vraag:'Wat leg je vast bij het vaststellen van de verplichtingen?',antwoord:`Leg per verplichting vast:
- de bron, zoals BKR, DUO of convenant
- het bedrag en de looptijd
- de manier waarop het in de toets is verwerkt
Leg ook vast dat de klant de opgave heeft bevestigd.
B:`,tags:['verplichtingen','dossier','vastlegging'],bron:''},
 {id:'hnx-189',thema:'hypotheek-normen',vraag:'Wat als de klant vlak voor de aanvraag een auto financiert?',antwoord:`Een nieuwe financiering verlaagt de leenruimte. De verplichting moet worden gemeld, ook als die nog niet in BKR staat. Bespreek vooraf de gevolgen van nieuwe kredieten tijdens het traject. Leg dit advies vast in het dossier.
B:`,tags:['autofinanciering','krediet','timing'],bron:''},
 {id:'hnx-190',thema:'hypotheek-normen',vraag:'Wat doe je met een verplichting die na de offerte ontstaat?',antwoord:`Een nieuwe verplichting kan de beoordeling veranderen. Meld deze aan de geldverstrekker. De geldverstrekker kan opnieuw toetsen of de offerte aanpassen. Leg de melding en de gevolgen vast.
B:`,tags:['offerte','nieuwe verplichting','meldplicht'],bron:''},
 {id:'hnx-191',thema:'hypotheek-normen',vraag:'Hoe toets je een stel met verschillende verplichtingen?',antwoord:`Tel de verplichtingen van beide aanvragers op. Beide aanvragers zijn in de regel hoofdelijk aansprakelijk voor de hypotheek. Bespreek ook verplichtingen die alleen op naam van een partner staan. Leg de verplichtingen per aanvrager vast.
B:`,tags:['stel','verplichtingen','hoofdelijkheid'],bron:''},
 {id:'hnx-192',thema:'hypotheek-normen',vraag:'Hoe ga je om met schulden in het buitenland?',antwoord:`Buitenlandse schulden staan niet in BKR. Vraag de klant er actief naar en vraag om stukken. Neem de lasten mee in de beoordeling. Controleer hoe de geldverstrekker dit beoordeelt.
B:`,tags:['buitenland','schulden','inventarisatie'],bron:''},
 {id:'hnx-193',thema:'hypotheek-normen',vraag:'Waar let je op bij een lopende huurovereenkomst na aankoop?',antwoord:`Door de opzegtermijn betaalt de klant soms tijdelijk huur en hypotheek tegelijk. Neem deze dubbele lasten mee in de beoordeling. Een geldverstrekker kan vragen of de klant ze kan dragen. Leg de opzegtermijn en de planning vast.
B:`,tags:['huur','opzegtermijn','dubbele lasten'],bron:''},
 {id:'hnx-194',thema:'hypotheek-normen',vraag:'Hoe beoordeel je dubbele lasten tijdens de bouw van een nieuwbouwwoning?',antwoord:`Tijdens de bouw betaalt de klant vaak huur of de oude hypotheek en daarnaast bouwrente. Die periode kan langer duren dan gepland. Toets of de klant de lasten ook bij vertraging kan dragen. Leg de planning en de afweging vast.
B:`,tags:['nieuwbouw','dubbele lasten','vertraging'],bron:''},
 {id:'hnx-195',thema:'hypotheek-normen',vraag:'Wat is bouwrente en hoe beïnvloedt die de lasten?',antwoord:`Bouwrente is rente die de ontwikkelaar rekent over grondkosten en bouwtermijnen die vóór de notariële levering zijn vervallen. Na levering betaalt de klant rente over de hypotheek, terwijl een deel nog in het depot staat. Beide bedragen raken de lasten tijdens de bouw. Neem ze mee in de planning.
B:`,tags:['bouwrente','nieuwbouw','lasten'],bron:''},
 {id:'hnx-196',thema:'hypotheek-normen',vraag:'Hoe werkt de rentevergoeding over een bouwdepot?',antwoord:`Over het bedrag in het depot ontvangt de klant vaak een rentevergoeding. Die vergoeding kan lager zijn dan de hypotheekrente. Het verschil is een extra last tijdens de bouw. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['bouwdepot','depotrente','lasten'],bron:''},
 {id:'hnx-197',thema:'hypotheek-normen',vraag:'Wat gebeurt er met een bouwdepot dat niet binnen de termijn is besteed?',antwoord:`Geldverstrekkers hanteren een termijn waarbinnen het depot moet worden gebruikt. Na die termijn kan het restant worden verrekend met de lening. Plan de werkzaamheden met de termijn in gedachten. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['bouwdepot','termijn','verrekening'],bron:''},
 {id:'hnx-198',thema:'hypotheek-normen',vraag:'Waarom vragen geldverstrekkers de herkomst van eigen middelen?',antwoord:`Geldverstrekkers moeten op grond van de Wwft de herkomst van middelen kunnen verklaren. Daarom vragen ze bankafschriften of andere bewijzen. Onverklaarbare stortingen leiden tot vragen of afwijzing. Leg de herkomst vast in het dossier.`,tags:['eigen middelen','herkomst','wwft'],bron:'Wwft'},
 {id:'hnx-199',thema:'hypotheek-normen',vraag:'Hoe toon je een schenking voor de aankoop aan?',antwoord:`Gebruikelijk zijn een schenkingsovereenkomst en bankafschriften van de overboeking. Vermeld of de schenking onder voorwaarden is gedaan. Let op de fiscale aangifte en de voorwaarden voor eventuele vrijstellingen; het actuele bedrag staat bij de Belastingdienst. Leg de stukken vast in het dossier.`,tags:['schenking','eigen middelen','documenten'],bron:'Belastingdienst'},
 {id:'hnx-200',thema:'hypotheek-normen',vraag:'Wat zijn veelgemaakte fouten bij het in kaart brengen van verplichtingen?',antwoord:`Veel voorkomende fouten zijn:
- alleen op BKR vertrouwen
- de studieschuld niet opvragen
- een ongebruikte kredietlimiet niet meetellen
- alimentatie uit een oud convenant gebruiken
Vraag actief door en controleer de bankafschriften. Leg de inventarisatie vast.
B:`,tags:['fouten','verplichtingen','inventarisatie'],bron:''},
 {id:'hnx-201',thema:'hypotheek-normen',vraag:'Wie beslist over een explain-lening: de adviseur of de geldverstrekker?',antwoord:`De geldverstrekker beslist of een afwijking van de normen wordt toegestaan. De adviseur onderbouwt de aanvraag en beoordeelt zelf of het advies passend is. Een akkoord van de geldverstrekker ontslaat de adviseur niet van de zorgplicht. Leg beide beoordelingen vast in het dossier.`,tags:['explain','geldverstrekker','zorgplicht'],bron:'Trhk'},
 {id:'hnx-202',thema:'hypotheek-normen',vraag:'Mag je een explain-lening adviseren omdat de klant daarom vraagt?',antwoord:`De wens van de klant is op zichzelf geen onderbouwing. Een afwijking moet verantwoord zijn op basis van de feiten. Beoordeel of de klant de lasten werkelijk kan dragen. Leg de feiten en je conclusie vast in het dossier.`,tags:['explain','klantwens','zorgplicht'],bron:'Wft'},
 {id:'hnx-203',thema:'hypotheek-normen',vraag:'Welke feiten kunnen onderbouwen dat een lening boven de norm verantwoord is?',antwoord:`Voorbeelden van onderbouwing zijn:
- aantoonbaar lage vaste lasten
- een ruime financiële buffer of vermogen
- een vastgelegde inkomensstijging
- tijdelijke aard van de overschrijding
Onderbouw met stukken en niet alleen met verklaringen. Leg de stukken vast in het dossier.`,tags:['explain','onderbouwing','buffer'],bron:'Trhk'},
 {id:'hnx-204',thema:'hypotheek-normen',vraag:'Is een verwachte inkomensstijging een grond voor een explain-lening?',antwoord:`Alleen een stijging die voldoende zeker en aantoonbaar is, kan een rol spelen. Een verwachting zonder vastlegging is onvoldoende. Ook dan beslist de geldverstrekker. Leg de onderbouwing en de beslissing vast.`,tags:['explain','inkomensstijging','onderbouwing'],bron:'Trhk'},
 {id:'hnx-205',thema:'hypotheek-normen',vraag:'Is een hoge huidige huur een argument voor een hogere hypotheek?',antwoord:`Een hoge huur die de klant al lang betaalt, zegt iets over het betaalgedrag. Het verandert de norm niet. Sommige geldverstrekkers nemen dit mee in een maatwerkbeoordeling. Controleer de voorwaarden en leg de huurhistorie vast.
B:`,tags:['huur','maatwerk','betaalgedrag'],bron:''},
 {id:'hnx-206',thema:'hypotheek-normen',vraag:'Hoe toets je een klant die na scheiding de woning wil overnemen?',antwoord:`De blijvende partner wordt getoetst op het eigen inkomen, inclusief alimentatie. Voor een alleenstaande geldt de verhoging van het toetsinkomen. De vertrekkende partner moet worden ontslagen uit de hoofdelijke aansprakelijkheid. Controleer de voorwaarden en leg de toets vast.`,tags:['scheiding','overname','hoofdelijkheid'],bron:'Trhk'},
 {id:'hnx-207',thema:'hypotheek-normen',vraag:'Wat is ontslag uit hoofdelijke aansprakelijkheid?',antwoord:`Bij ontslag is een vertrekkende partner niet meer aansprakelijk voor de hypotheek. De geldverstrekker beslist hierover na toetsing van de blijvende partner. Zonder ontslag blijft de vertrekkende partner aansprakelijk. Leg de beslissing van de geldverstrekker vast.
B:`,tags:['hoofdelijkheid','ontslag','scheiding'],bron:''},
 {id:'hnx-208',thema:'hypotheek-normen',vraag:'Wordt de hypotheek opnieuw getoetst na overlijden van een partner?',antwoord:`Bij overlijden loopt de bestaande hypotheek in de regel door. De nabestaande blijft aansprakelijk. Een nieuwe toets volgt meestal pas bij een wijziging, zoals een verhoging of oversluiten. Bespreek de betaalbaarheid en eventuele verzekeringsuitkeringen met de nabestaande.
B:`,tags:['overlijden','nabestaande','bestaande hypotheek'],bron:''},
 {id:'hnx-209',thema:'hypotheek-normen',vraag:'Waar let je op bij een senior die naar een goedkopere woning verhuist?',antwoord:`Na de AOW-leeftijd gelden aparte financieringslasttabellen. Door een lager inkomen kan de maximale lening lager zijn dan de huidige. De overwaarde en de nieuwe lasten bepalen of verhuizen haalbaar is. Leg de afweging vast en controleer de voorwaarden.`,tags:['senioren','aow','verhuizen'],bron:'Trhk'},
 {id:'hnx-210',thema:'hypotheek-normen',vraag:'Hoe verhoudt een verzilverhypotheek zich tot de normen?',antwoord:`Bij zulke producten wordt de rente vaak bijgeschreven of beperkt betaald. De LTV-ruimte en de leeftijd van de klant zijn daarbij belangrijk. Er gelden aparte voorwaarden van de geldverstrekker. Bespreek de groei van de schuld en leg de afweging vast.
B:`,tags:['verzilveren','senioren','overwaarde'],bron:''},
 {id:'hnx-211',thema:'hypotheek-normen',vraag:'Wat is het verschil tussen een explain-lening en een uitzondering op het eigen beleid?',antwoord:`Bij een explain-lening wijkt de geldverstrekker af van de Trhk. Bij een uitzondering op eigen beleid wijkt hij af van zijn eigen, strengere regels, maar blijft binnen de Trhk. Voor beide is een onderbouwing nodig. Benoem in het dossier welk soort afwijking het is.`,tags:['explain','acceptatiebeleid','uitzondering'],bron:'Trhk'},
 {id:'hnx-212',thema:'hypotheek-normen',vraag:'Welke opties zijn er als de lening net boven de LTV-grens uitkomt?',antwoord:`Mogelijke routes zijn een hogere eigen inbreng of een lager leenbedrag. Overschrijding is alleen toegestaan voor energiebesparende voorzieningen. Gebruik die route niet zonder echte maatregelen. Leg de gekozen oplossing vast.`,tags:['ltv','eigen inbreng','verduurzaming'],bron:'Trhk'},
 {id:'hnx-213',thema:'hypotheek-normen',vraag:'Mag je een lening opknippen om de normen te omzeilen?',antwoord:`Nee, de normen gelden voor de totale kredietverlening voor de woning. Een tweede lening elders telt ook mee. Opknippen om de toets te ontlopen is in strijd met het doel van de regels. Leg de totale financiering vast in het dossier.`,tags:['opknippen','normen','totale lening'],bron:'Trhk'},
 {id:'hnx-214',thema:'hypotheek-normen',vraag:'Wat doe je als de klant na het passeren een consumptief krediet wil afsluiten?',antwoord:`Dat krediet valt buiten de hypotheektoets, maar raakt de betaalbaarheid. Wijs de klant op de gevolgen voor het budget. Een kredietverstrekker toetst wel de bestaande hypotheeklasten. Leg het advies vast in het dossier.
B:`,tags:['krediet','na passeren','betaalbaarheid'],bron:''},
 {id:'hnx-215',thema:'hypotheek-normen',vraag:'Welke rol speelt het klantprofiel bij de normtoets?',antwoord:`De normtoets geeft een maximum. Het klantprofiel bepaalt wat binnen dat maximum passend is. Denk aan risicobereidheid, buffers, toekomstplannen en kennis. Leg het profiel en de koppeling met het advies vast.`,tags:['klantprofiel','passendheid','zorgplicht'],bron:'Wft'},
 {id:'hnx-216',thema:'hypotheek-normen',vraag:'Welke normgegevens leg je vast in het adviesrapport?',antwoord:`Leg minimaal vast:
- het jaar van de gebruikte normen
- de toetsrente en het kwartaal
- het toetsinkomen en de opbouw daarvan
- de meegenomen verplichtingen
- de gebruikte marktwaarde
Zo kan een ander de berekening navolgen.
B:`,tags:['adviesrapport','vastlegging','normen'],bron:''},
 {id:'hnx-217',thema:'hypotheek-normen',vraag:'Hoe lang bewaar je het dossier met de toetsing?',antwoord:`Volg de bewaartermijnen uit wet- en regelgeving en uit het eigen beleid. Het dossier moet de toetsing en de afwegingen navolgbaar maken. Een toezichthouder of klachtinstantie kan het later opvragen. Bewaar het dossier volledig en ordelijk.
B:`,tags:['bewaartermijn','dossier','vastlegging'],bron:''},
 {id:'hnx-218',thema:'hypotheek-normen',vraag:'Hoe ga je om met een aanvraag rond de jaarwisseling als de normen wijzigen?',antwoord:`De normen in de Trhk worden in de regel per kalenderjaar aangepast. Rond de jaarwisseling kan het moment van toetsen dus verschil maken. Bepaal welk moment de geldverstrekker hanteert. Leg vast met welke normen is getoetst.`,tags:['jaarwisseling','normen','timing'],bron:'Trhk'},
 {id:'hnx-219',thema:'hypotheek-normen',vraag:'Wat moet je vastleggen bij een comply-lening?',antwoord:`Ook bij een lening binnen de normen moet de toetsing navolgbaar zijn. Leg het toetsinkomen, de toetsrente, de verplichtingen en de marktwaarde vast. Leg ook vast waarom de lening passend is. Een lening binnen de normen is niet automatisch passend.`,tags:['comply','vastlegging','passendheid'],bron:'Wft'},
 {id:'hnx-220',thema:'hypotheek-normen',vraag:'Welke signalen wijzen erop dat een comply-lening toch niet passend is?',antwoord:`Voorbeelden zijn:
- een verwachte inkomensdaling
- hoge vaste lasten buiten de norm
- weinig buffer
- een korte rentevaste periode bij krappe ruimte
Bespreek deze signalen met de klant. Leg de afweging vast.`,tags:['comply','signalen','passendheid'],bron:'Wft'},
 {id:'hnx-221',thema:'hypotheek-normen',vraag:'Wat doe je als de klant tegen advies een hogere lening wil?',antwoord:`Leg het advies en de afwijkende keuze van de klant vast. Wijs de klant op de risicos. Een lening boven de normen kun je niet zelf toestaan; de geldverstrekker beslist. Overweeg of je de dienstverlening kunt voortzetten.`,tags:['afwijkend advies','klantkeuze','vastlegging'],bron:'Wft'},
 {id:'hnx-222',thema:'hypotheek-normen',vraag:'Kan een klant zonder advies een hypotheek boven de normen krijgen?',antwoord:`De Trhk geldt voor de geldverstrekker, ook als de klant geen advies krijgt. Een afwijking blijft dus een beslissing van de geldverstrekker. Zonder advies vervalt de normtoets niet. Controleer de voorwaarden van de geldverstrekker.`,tags:['execution only','trhk','geldverstrekker'],bron:'Trhk'},
 {id:'hnx-223',thema:'hypotheek-normen',vraag:'Hoe weeg je een starter met een kleine spaarbuffer?',antwoord:`De normen stellen geen eis aan een buffer. Een kleine buffer maakt de klant wel kwetsbaar voor onverwachte kosten. Bespreek dit en houd rekening met onderhoud en inrichting. Leg de afweging vast in het dossier.
B:`,tags:['starter','buffer','zorgplicht'],bron:''},
 {id:'hnx-224',thema:'hypotheek-normen',vraag:'Hoe beïnvloedt een kortere rentevaste periode de maximale hypotheek?',antwoord:`Bij een rentevaste periode korter dan 10 jaar geldt minimaal de AFM-toetsrente. Ligt die boven de werkelijke rente, dan is de leenruimte lager. Bij een periode van 10 jaar of langer toets je met de werkelijke rente. Vergelijk beide uitkomsten en leg ze vast.`,tags:['rentevaste periode','toetsrente','leenruimte'],bron:'Trhk'},
 {id:'hnx-225',thema:'hypotheek-normen',vraag:'Hoe bespreek je het renterisico bij een korte rentevaste periode?',antwoord:`Bij een korte rentevaste periode kan de rente na afloop stijgen. Laat de klant zien wat een hogere rente betekent voor de maandlast. Beoordeel of de klant die stijging kan dragen. Leg het scenario en de afweging vast.`,tags:['renterisico','rentevaste periode','scenario'],bron:'Wft'},
 {id:'hnx-226',thema:'hypotheek-normen',vraag:'Hoe toets je twee aanvragers die geen partners zijn?',antwoord:`Beide aanvragers worden getoetst en worden in de regel hoofdelijk aansprakelijk. Of de verhoging voor alleenstaanden van toepassing is, hangt af van de werkwijze van de geldverstrekker. Bespreek afspraken over eigendom en vertrek van een van beiden. Controleer de voorwaarden en leg de afspraken vast.
B:`,tags:['samen kopen','hoofdelijkheid','aanvragers'],bron:''},
 {id:'hnx-227',thema:'hypotheek-normen',vraag:'Waar let je op bij een ongelijke eigendomsverdeling tussen aanvragers?',antwoord:`De eigendom kan ongelijk zijn, terwijl beide aanvragers hoofdelijk aansprakelijk zijn. Dat heeft gevolgen voor de onderlinge verhouding en de fiscale verdeling. Adviseer de klanten om afspraken notarieel vast te leggen. Leg de verdeling vast in het dossier.
B:`,tags:['eigendom','hoofdelijkheid','fiscale verdeling'],bron:''},
 {id:'hnx-228',thema:'hypotheek-normen',vraag:'Wanneer is een nieuwe toets nodig bij een bestaande hypotheek?',antwoord:`Een nieuwe toets volgt bij een nieuwe kredietverlening. Denk aan een verhoging, oversluiten naar een andere geldverstrekker of het toevoegen van een schuldenaar. Ook bij ontslag uit hoofdelijke aansprakelijkheid toetst de geldverstrekker de blijvende partner. Controleer de voorwaarden van de geldverstrekker.`,tags:['bestaande hypotheek','nieuwe toets','verhoging'],bron:'Trhk'},
 {id:'hnx-229',thema:'hypotheek-normen',vraag:'Is een renteherziening aan het eind van de rentevaste periode een nieuwe kredietverlening?',antwoord:`Een renteherziening binnen een bestaande lening bij dezelfde geldverstrekker leidt in de regel niet tot een volledige nieuwe toets. De lening blijft immers bestaan. De zorgplicht bij advies over de nieuwe rentevaste periode blijft wel gelden. Controleer de voorwaarden van de geldverstrekker.
B:`,tags:['renteherziening','rentevaste periode','toetsing'],bron:''},
 {id:'hnx-230',thema:'hypotheek-normen',vraag:'Wat zijn de fiscale gevolgen van een andere aflossingsvorm binnen een bestaande lening?',antwoord:`Voor schuld van na 2012 geldt de aflossingseis van ten minste annuïtair over 360 maanden. Wordt een deel aflossingsvrij, dan voldoet dat deel niet meer en valt het in box 3. Voor schuld onder overgangsrecht ligt dat anders. Laat de fiscale gevolgen beoordelen vóór de wijziging.`,tags:['aflossingsvorm','aflossingseis','box 3'],bron:'Wet IB 2001'},
 {id:'hnx-231',thema:'hypotheek-normen',vraag:'Wat gebeurt er met overgangsrecht bij oversluiten?',antwoord:`Het overgangsrecht blijft in de regel gelden voor het bedrag van de bestaande eigenwoningschuld. Een verhoging valt onder de aflossingseis. Houd de delen daarom fiscaal gescheiden. Leg de fiscale historie van elk deel vast.`,tags:['overgangsrecht','oversluiten','aflossingseis'],bron:'Wet IB 2001'},
 {id:'hnx-232',thema:'hypotheek-normen',vraag:'Hoe toets je een klant die in het buitenland woont en in Nederland koopt?',antwoord:`Geldverstrekkers stellen vaak extra eisen aan aanvragers die buiten Nederland wonen. Denk aan inkomen, valuta en de vraag of de woning het hoofdverblijf wordt. Ook de fiscale behandeling kan afwijken. Controleer de voorwaarden en laat de fiscale positie beoordelen.
B:`,tags:['buitenland','niet-ingezetene','acceptatie'],bron:''},
 {id:'hnx-233',thema:'hypotheek-normen',vraag:'Wat doe je als de geldverstrekker een andere uitkomst geeft dan je eigen berekening?',antwoord:`Zoek de oorzaak van het verschil. Vaak gaat het om toetsrente, inkomen of de weging van verplichtingen. De berekening van de geldverstrekker is leidend voor de acceptatie. Leg het verschil en de verklaring vast.
B:`,tags:['berekening','verschil','geldverstrekker'],bron:''},
 {id:'hnx-234',thema:'hypotheek-normen',vraag:'Wat kun je doen als de aanvraag net buiten de normen valt door een kleine verplichting?',antwoord:`Mogelijke routes zijn het aflossen van het krediet of het opzeggen van een ongebruikte limiet. Het bewijs van beëindiging moet dan voor de geldverstrekker beschikbaar zijn. Bespreek of deze route in het belang van de klant is. Leg de afweging vast.
B:`,tags:['verplichtingen','aflossen','leenruimte'],bron:''},
 {id:'hnx-235',thema:'hypotheek-normen',vraag:'Wat leg je vast als een hypotheekwens niet haalbaar is?',antwoord:`Leg vast welke lening de klant wilde en waarom die niet haalbaar is. Noteer de berekening en de alternatieven die je hebt besproken. Leg ook vast hoe de klant de uitkomst heeft ontvangen. Zo is later navolgbaar wat er is geadviseerd.
B:`,tags:['afwijzing','vastlegging','alternatieven'],bron:''},
 {id:'hnx-236',thema:'hypotheek-normen',vraag:'Hoe weeg je een verwachte gezinsuitbreiding in de betaalbaarheid?',antwoord:`Een gezinsuitbreiding valt buiten de normtoets. Het kan wel leiden tot hogere kosten of minder werken. Bespreek de gevolgen voor het budget. Leg het gesprek en de afweging vast.`,tags:['gezinsuitbreiding','betaalbaarheid','zorgplicht'],bron:'Wft'},
 {id:'hnx-237',thema:'hypotheek-normen',vraag:'Welke rol spelen een zelfbewoningsplicht of antispeculatiebeding bij de acceptatie?',antwoord:`Zulke bedingen beperken verhuur of doorverkoop. Ze kunnen de waarde en courantheid van het onderpand beïnvloeden. Geldverstrekkers stellen soms eisen aan de inhoud van zo een beding. Controleer de voorwaarden en leg het beding vast.
B:`,tags:['zelfbewoningsplicht','antispeculatiebeding','onderpand'],bron:''},
 {id:'hnx-238',thema:'hypotheek-normen',vraag:'Hoe toets je een woning met een koopconstructie met korting?',antwoord:`Bij een koopconstructie met korting wijkt de koopsom af van de marktwaarde. Er zijn vaak afspraken over terugkoop en verdeling van waardeontwikkeling. Geldverstrekkers financieren dit alleen onder specifieke voorwaarden. Controleer de voorwaarden en leg de constructie vast.
B:`,tags:['koopconstructie','korting','marktwaarde'],bron:''},
 {id:'hnx-239',thema:'hypotheek-normen',vraag:'Hoe verhoudt de leenruimte van een alleenstaande zich tot die van een stel?',antwoord:`Een alleenstaande krijgt een verhoging van het toetsinkomen met €17.000. Een stel met hetzelfde totale inkomen krijgt die verhoging niet. Bij gelijk inkomen heeft een alleenstaande daardoor meer leenruimte op basis van de norm. De werkelijke lasten van een eenpersoonshuishouden blijven een aandachtspunt.`,tags:['alleenstaanden','stel','leenruimte'],bron:'Nibud Advies hypotheeknormen 2026'},
 {id:'hnx-240',thema:'hypotheek-normen',vraag:'Maakt de verdeling van het inkomen binnen een stel nog uit voor de toets?',antwoord:`Omdat het tweede inkomen volledig meetelt, is het gezamenlijke inkomen leidend. De verdeling tussen de partners heeft daardoor geen invloed op de normtoets. De verdeling is wel van belang voor risicos zoals overlijden en arbeidsongeschiktheid. Bespreek die risicos en leg ze vast.`,tags:['tweeverdieners','inkomensverdeling','risicos'],bron:'Nibud Advies hypotheeknormen 2026'},
 {id:'hnx-241',thema:'hypotheek-normen',vraag:'Hoe leg je de communicatie met de geldverstrekker over een uitzondering vast?',antwoord:`Bewaar de aanvraag, de motivering en het antwoord van de geldverstrekker. Noteer wie wat heeft besloten en op welke grond. Leg ook vast welke voorwaarden aan de uitzondering zijn verbonden. Zo is het dossier navolgbaar voor een toetsing achteraf.
B:`,tags:['uitzondering','communicatie','vastlegging'],bron:''},
 {id:'hnx-242',thema:'hypotheek-normen',vraag:'Waarover informeer je de klant bij een explain-lening?',antwoord:`Leg uit dat de lening boven de standaardnorm ligt. Bespreek de hogere lasten en de risicos bij tegenvallers. Controleer of de klant dit begrijpt. Leg de uitleg en de reactie van de klant vast.`,tags:['explain','informatie','risicos'],bron:'Wft'},
 {id:'hnx-243',thema:'hypotheek-normen',vraag:'Wat is een veelgemaakte fout bij het toepassen van de oversluitregeling?',antwoord:`Een veelgemaakte fout is ongemerkt een verhoging meenemen. Denk aan meegefinancierde kosten of een extra opname. Controleer of de geldverstrekker zo een verhoging nog binnen de uitzondering laat vallen. Leg het oude en het nieuwe leenbedrag vast.`,tags:['oversluiten','verhoging','uitzondering'],bron:'Trhk'},
 {id:'hnx-244',thema:'hypotheek-normen',vraag:'Kan het inkomen van een nieuwe partner meetellen kort na het samenwonen?',antwoord:`Het inkomen telt alleen mee als de partner medeaanvrager wordt. De partner wordt dan in de regel hoofdelijk aansprakelijk. Bespreek de gevolgen bij een eventuele breuk. Leg de afspraken vast en adviseer om ze notarieel te regelen.
B:`,tags:['nieuwe partner','medeaanvrager','hoofdelijkheid'],bron:''},
 {id:'hnx-245',thema:'hypotheek-normen',vraag:'Wat betekent hoofdelijke aansprakelijkheid voor een medeaanvrager zonder eigendom?',antwoord:`Een medeaanvrager zonder eigendom kan aansprakelijk zijn voor de hele schuld zonder recht op de woning. Ook de fiscale positie kan dan anders uitvallen. Bespreek dit risico met beide aanvragers. Leg de afspraken en de fiscale beoordeling vast.
B:`,tags:['hoofdelijkheid','eigendom','medeaanvrager'],bron:''},
 {id:'hnx-246',thema:'hypotheek-normen',vraag:'Kan een klant extra lenen om een buffer aan te houden?',antwoord:`Een lening voor een buffer is geen schuld voor de verwerving of verbetering van de woning. Dat deel is geen eigenwoningschuld en valt in box 3. Het telt ook mee voor de LTV-grens. Bespreek of dit in het belang van de klant is en leg dat vast.`,tags:['buffer','box 3','ltv'],bron:'Wet IB 2001'},
 {id:'hnx-247',thema:'hypotheek-normen',vraag:'Hoe beoordeel je of een explain-lening betaalbaar blijft na een renteherziening?',antwoord:`Een lening boven de norm geeft minder ruimte voor een rentestijging. Laat zien wat een hogere rente na de rentevaste periode betekent. Beoordeel of de klant dat scenario kan dragen. Leg het scenario en de conclusie vast.`,tags:['explain','renteherziening','scenario'],bron:'Wft'},
 {id:'hnx-248',thema:'hypotheek-normen',vraag:'Welke controles doe je vóór het indienen van een aanvraag?',antwoord:`Een korte checklist:
- inkomen en stukken consistent
- alle verplichtingen opgevraagd en verwerkt
- juiste toetsrente en normjaar
- marktwaarde en LTV gecontroleerd
- energielabel en eventuele maatregelen vastgelegd
Leg de controle vast in het dossier.
B:`,tags:['checklist','aanvraag','controle'],bron:''},
 {id:'hnx-249',thema:'hypotheek-normen',vraag:'Welke rol heeft de AFM bij de leennormen?',antwoord:`De AFM houdt toezicht op de naleving van de Wft en de Trhk door geldverstrekkers en adviseurs. Daarnaast stelt de AFM per kwartaal de minimale toetsrente vast. Zij kan dossiers opvragen en beoordelen. Zorg dat de afwegingen navolgbaar zijn vastgelegd.`,tags:['afm','toezicht','toetsrente'],bron:'AFM'},
 {id:'hnx-250',thema:'hypotheek-normen',vraag:'Wat zijn veelgemaakte fouten in explain- en comply-dossiers?',antwoord:`Veel voorkomende fouten zijn:
- geen onderbouwing waarom de lening passend is
- een explain zonder stukken
- niet benoemen welke norm wordt overschreden
- geen vastlegging van het besluit van de geldverstrekker
Controleer het dossier op deze punten. Leg ontbrekende onderdelen alsnog vast.
B:`,tags:['fouten','explain','comply'],bron:''},
]);
